-- Non-default scenarios with empty entry conditions must not steal spawn
-- from the default scenario (they always "match" and have no templates).

create or replace function public.automation_spawn_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := coalesce(OLD.field_values, '{}'::jsonb);
  new_values jsonb := coalesce(NEW.field_values, '{}'::jsonb);
  proc record;
  scenario record;
  tmpl record;
  old_opt text;
  new_opt text;
  old_opt_id text;
  new_opt_id text;
  assignee_ids text[];
  assignee_id text;
  task_id text;
  task_name text;
  task_description text;
  due timestamptz;
  template_snapshot jsonb;
  entered boolean;
  depth text;
  n_msg text;
  actor text;
  stored_option_id text;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = NEW.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    old_opt := coalesce(old_values->>proc.trigger_field_id, '');
    new_opt := coalesce(new_values->>proc.trigger_field_id, '');
    old_opt_id := coalesce((public.automation_field_ids(old_opt))[1], '');
    new_opt_id := coalesce((public.automation_field_ids(new_opt))[1], '');

    if TG_OP = 'UPDATE'
       and old_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_assert_no_blocking(
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        old_opt_id
      );
    end if;

    entered := false;
    if proc.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      entered := true;
    elsif proc.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      entered := old_values is distinct from new_values;
    elsif proc.trigger_kind in ('fieldEnter', 'fieldTransition') then
      entered := new_opt_id is distinct from old_opt_id and new_opt_id <> '';
    elsif proc.trigger_kind = 'fieldLeave' then
      entered := new_opt_id is distinct from old_opt_id and old_opt_id <> '';
    end if;

    if not entered then
      continue;
    end if;

    -- Only non-default scenarios with real entry rules can override default.
    -- Empty conditions always "match" and would steal spawn from «Основной».
    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, new_values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and (
          t.trigger_option_id = ''
          or t.trigger_option_id = new_opt
          or t.trigger_option_id = new_opt_id
          or t.trigger_option_id = any(public.automation_field_ids(new_opt))
        )
        and public.automation_conditions_match(t.launch_conditions, new_values, old_values)
    loop
      assignee_ids := public.automation_resolve_assignees(tmpl.assignee, new_values, actor);
      -- Empty field/relation assignee → current user so the dialog still opens.
      if cardinality(assignee_ids) = 0 then
        assignee_ids := public.automation_resolve_assignees(
          '{"type":"currentUser"}'::jsonb,
          new_values,
          actor
        );
      end if;
      if cardinality(assignee_ids) = 0 then
        assignee_ids := array[null::text];
      end if;

      template_snapshot := jsonb_build_object(
        'id', tmpl.id,
        'scenarioId', tmpl.scenario_id,
        'name', tmpl.name,
        'nameTemplate', tmpl.name_template,
        'description', tmpl.description,
        'triggerOptionId', tmpl.trigger_option_id,
        'stepOrder', tmpl.step_order,
        'isBlocking', tmpl.is_blocking,
        'kind', tmpl.kind,
        'launchConditions', tmpl.launch_conditions,
        'assignee', tmpl.assignee,
        'watchers', tmpl.watchers,
        'outcomes', tmpl.outcomes,
        'sla', tmpl.sla,
        'materials', tmpl.materials
      );

      task_name := public.automation_render_template(
        case
          when nullif(btrim(tmpl.name_template), '') is not null then tmpl.name_template
          else tmpl.name
        end,
        new_values
      );
      if nullif(btrim(task_name), '') is null then
        task_name := tmpl.name;
      end if;

      task_description := public.automation_render_template(
        coalesce(tmpl.description, ''),
        new_values
      );

      due := null;
      if tmpl.sla is not null and (tmpl.sla->>'hours') is not null then
        begin
          due := now() + ((tmpl.sla->>'hours')::numeric || ' hours')::interval;
        exception when others then
          due := null;
        end;
      end if;

      stored_option_id := coalesce(
        nullif(tmpl.trigger_option_id, ''),
        nullif(new_opt_id, ''),
        new_opt
      );

      foreach assignee_id in array assignee_ids
      loop
        task_id := 'atask-' || gen_random_uuid()::text;
        begin
          insert into public.automation_tasks (
            id, process_id, scenario_id, template_id,
            entity_id, record_id, trigger_field_id, trigger_option_id,
            assignee_user_id, status, is_blocking, step_order,
            name, description, config, due_at
          ) values (
            task_id,
            proc.id,
            scenario.id,
            tmpl.id,
            NEW.entity_id,
            NEW.id,
            proc.trigger_field_id,
            stored_option_id,
            assignee_id,
            'pending',
            tmpl.is_blocking,
            tmpl.step_order,
            task_name,
            task_description,
            template_snapshot,
            due
          );
        exception
          when unique_violation then
            continue;
          when others then
            raise warning 'automation spawn insert failed: %', sqlerrm;
            continue;
        end;

        begin
          for n_msg in
            select coalesce(nullif(r.message_template, ''), 'Назначена задача: ' || task_name)
            from public.automation_notification_rules r
            where r.template_id = tmpl.id
              and r.event = 'assigned'
          loop
            perform public.create_notification(
              coalesce(assignee_id, auth.uid()::text),
              'Назначена задача',
              n_msg,
              'automation',
              null,
              NEW.entity_id,
              NEW.id,
              task_id,
              true
            );
          end loop;
        exception when others then
          raise warning 'automation spawn notify failed: %', sqlerrm;
        end;
      end loop;
    end loop;
  end loop;

  return NEW;
end;
$$;
-- <<< END 20261016250000_automation_spawn_scenario_select.sql

-- >>> BEGIN 20261016260000_automation_folder_files_condition.sql
-- Conditions: folderHasFiles / folderEmpty against files-tree JSON values.

create or replace function public.automation_count_files_in_named_folder(
  p_raw text,
  p_folder_name text
) returns integer
language plpgsql
immutable
as $$
declare
  entries jsonb;
  folder_id text;
  folder_name text := lower(btrim(coalesce(p_folder_name, '')));
  cnt integer := 0;
  item jsonb;
begin
  if folder_name = '' or p_raw is null or btrim(p_raw) = '' then
    return 0;
  end if;

  begin
    entries := p_raw::jsonb;
  exception when others then
    return 0;
  end;

  if jsonb_typeof(entries) <> 'array' then
    return 0;
  end if;

  folder_id := null;
  for item in select * from jsonb_array_elements(entries)
  loop
    if coalesce(item->>'kind', '') = 'folder'
       and lower(btrim(coalesce(item->>'name', ''))) = folder_name
    then
      folder_id := item->>'id';
      exit;
    end if;
  end loop;

  if folder_id is null or folder_id = '' then
    return 0;
  end if;

  select count(*)::integer into cnt
  from jsonb_array_elements(entries) as t(item)
  where coalesce(item->>'kind', '') = 'file'
    and coalesce(item->>'parentId', '') = folder_id;

  return coalesce(cnt, 0);
end;
$$;

create or replace function public.automation_condition_rule_match(
  rule jsonb,
  p_values jsonb,
  previous_values jsonb
) returns boolean
language plpgsql
immutable
as $$
declare
  field_id text := coalesce(rule->>'fieldId', '');
  op text := coalesce(rule->>'operator', '');
  current text := coalesce(p_values->>field_id, '');
  previous text := coalesce(previous_values->>field_id, '');
  current_ids text[] := public.automation_field_ids(current);
  wanted text[];
  rule_value text := rule->>'value';
  left_n numeric;
  right_n numeric;
  from_v text;
  to_v text;
  file_count integer;
begin
  if field_id = '' or op = '' then
    return true;
  end if;

  if jsonb_typeof(rule->'values') = 'array' then
    wanted := coalesce(
      (select array_agg(x) from jsonb_array_elements_text(rule->'values') as t(x)),
      array[]::text[]
    );
  elsif rule_value is not null and rule_value <> '' then
    wanted := array[rule_value];
  else
    wanted := array[]::text[];
  end if;

  case op
    when 'empty' then
      return current = '' or cardinality(current_ids) = 0;
    when 'notEmpty' then
      return current <> '';
    when 'equals' then
      return current = coalesce(rule_value, '') or coalesce(rule_value, '') = any(current_ids);
    when 'notEquals' then
      return current <> coalesce(rule_value, '') and not (coalesce(rule_value, '') = any(current_ids));
    when 'contains' then
      return position(lower(coalesce(rule_value, '')) in lower(current)) > 0;
    when 'notContains' then
      return position(lower(coalesce(rule_value, '')) in lower(current)) = 0;
    when 'gt', 'gte', 'lt', 'lte' then
      begin
        left_n := replace(current, ',', '.')::numeric;
        right_n := replace(coalesce(rule_value, ''), ',', '.')::numeric;
      exception when others then
        return false;
      end;
      if op = 'gt' then return left_n > right_n; end if;
      if op = 'gte' then return left_n >= right_n; end if;
      if op = 'lt' then return left_n < right_n; end if;
      return left_n <= right_n;
    when 'in' then
      return exists (select 1 from unnest(wanted) w where w = current or w = any(current_ids));
    when 'notIn' then
      return not exists (select 1 from unnest(wanted) w where w = current or w = any(current_ids));
    when 'includesAny' then
      return exists (select 1 from unnest(wanted) w where w = any(current_ids));
    when 'includesAll' then
      return wanted <@ current_ids;
    when 'true' then
      return current = 'true';
    when 'false' then
      return current is distinct from 'true';
    when 'fieldChanged' then
      return current is distinct from previous;
    when 'fieldTransition' then
      begin
        from_v := rule_value::jsonb->>'from';
        to_v := rule_value::jsonb->>'to';
      exception when others then
        to_v := rule_value;
        from_v := null;
      end;
      if from_v is not null and from_v <> '' and previous is distinct from from_v then
        return false;
      end if;
      if to_v is not null and to_v <> '' and current is distinct from to_v and not (to_v = any(current_ids)) then
        return false;
      end if;
      return current is distinct from previous;
    when 'folderHasFiles' then
      file_count := public.automation_count_files_in_named_folder(current, coalesce(rule_value, ''));
      return file_count > 0;
    when 'folderEmpty' then
      file_count := public.automation_count_files_in_named_folder(current, coalesce(rule_value, ''));
      return file_count = 0;
    else
      return true;
  end case;
end;
$$;
-- <<< END 20261016260000_automation_folder_files_condition.sql

-- >>> BEGIN 20261016270000_automation_resolve_entity_path.sql
-- Resolve `{{relationFieldId.nestedFieldId}}` action values from a related
-- record when completing automation tasks in SQL.

create or replace function public.automation_resolve_related_field_value(
  p_relation_field_id text,
  p_nested_field_id text,
  p_field_values jsonb
)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rel_raw text;
  related_id text;
  nested_val text;
begin
  if p_relation_field_id is null or length(trim(p_relation_field_id)) = 0 then
    return '';
  end if;
  if p_nested_field_id is null or length(trim(p_nested_field_id)) = 0 then
    return '';
  end if;

  rel_raw := coalesce(p_field_values->>p_relation_field_id, '');
  if rel_raw = '' then
    return '';
  end if;

  -- Relation values: JSON array, CSV, or a single id.
  if left(rel_raw, 1) = '[' then
    begin
      related_id := nullif(trim(rel_raw::jsonb->>0), '');
    exception when others then
      related_id := null;
    end;
  else
    related_id := nullif(trim(split_part(rel_raw, ',', 1)), '');
  end if;

  if related_id is null then
    return '';
  end if;

  select er.field_values->>p_nested_field_id
    into nested_val
  from public.entity_records er
  where er.id = related_id
  limit 1;

  return coalesce(nested_val, '');
end;
$$;

create or replace function public.automation_resolve_action_value(
  p_value text,
  p_field_values jsonb,
  p_actor_user_id text default null
)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v text := coalesce(p_value, '');
  user_id text;
  relation_field_id text;
  nested_field_id text;
begin
  if v = '' then
    return '';
  end if;

  if v = '__today__' then
    return to_char(current_date, 'YYYY-MM-DD');
  end if;

  if v = '__tomorrow__' then
    return to_char(current_date + 1, 'YYYY-MM-DD');
  end if;

  if v = '__now__' then
    return to_char(clock_timestamp(), 'YYYY-MM-DD"T"HH24:MI');
  end if;

  if v = '__timeNow__' then
    return to_char(clock_timestamp(), 'HH24:MI');
  end if;

  if v = '__currentUser__' then
    if p_actor_user_id is not null and length(trim(p_actor_user_id)) > 0 then
      return trim(p_actor_user_id);
    end if;
    select er.id into user_id
    from public.entity_records er
    where er.entity_id = 'entity-system-users'
      and er.auth_user_id = auth.uid()
    limit 1;
    return coalesce(user_id, '');
  end if;

  if v = '{{created}}' or v = 'created' then
    return '';
  end if;

  -- `{{relationFieldId.nestedFieldId}}` — value from the related record.
  if v ~ '^\{\{[^.}]+\.[^}]+\}\}$' then
    relation_field_id := substring(v from '\{\{([^.]+)\.');
    nested_field_id := substring(v from '\.([^}]+)\}\}');
    return public.automation_resolve_related_field_value(
      relation_field_id,
      nested_field_id,
      p_field_values
    );
  end if;

  return public.automation_render_template(v, p_field_values);
end;
$$;
-- <<< END 20261016270000_automation_resolve_entity_path.sql

-- >>> BEGIN 20261016280000_automation_autofill_spawn.sql
-- Autofill step kind: spawn a task and complete it immediately (setField etc.).
-- Used for silent field fills on record create / stage enter — no user button.

create or replace function public.automation_spawn_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := coalesce(OLD.field_values, '{}'::jsonb);
  new_values jsonb := coalesce(NEW.field_values, '{}'::jsonb);
  proc record;
  scenario record;
  tmpl record;
  old_opt text;
  new_opt text;
  old_opt_id text;
  new_opt_id text;
  assignee_ids text[];
  assignee_id text;
  task_id text;
  task_name text;
  task_description text;
  due timestamptz;
  template_snapshot jsonb;
  entered boolean;
  depth text;
  n_msg text;
  actor text;
  stored_option_id text;
  autofill_outcome_id text;
  outcome_elem jsonb;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = NEW.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    old_opt := coalesce(old_values->>proc.trigger_field_id, '');
    new_opt := coalesce(new_values->>proc.trigger_field_id, '');
    old_opt_id := coalesce((public.automation_field_ids(old_opt))[1], '');
    new_opt_id := coalesce((public.automation_field_ids(new_opt))[1], '');

    if TG_OP = 'UPDATE'
       and old_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_assert_no_blocking(
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        old_opt_id
      );
    end if;

    entered := false;
    if proc.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      entered := true;
    elsif proc.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      entered := old_values is distinct from new_values;
    elsif proc.trigger_kind in ('fieldEnter', 'fieldTransition') then
      entered := new_opt_id is distinct from old_opt_id and new_opt_id <> '';
    elsif proc.trigger_kind = 'fieldLeave' then
      entered := new_opt_id is distinct from old_opt_id and old_opt_id <> '';
    end if;

    if not entered then
      continue;
    end if;

    -- Only non-default scenarios with real entry rules can override default.
    -- Empty conditions always "match" and would steal spawn from «Основной».
    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, new_values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and (
          t.trigger_option_id = ''
          or t.trigger_option_id = new_opt
          or t.trigger_option_id = new_opt_id
          or t.trigger_option_id = any(public.automation_field_ids(new_opt))
        )
        and public.automation_conditions_match(t.launch_conditions, new_values, old_values)
    loop
      if tmpl.kind = 'autofill' then
        -- One silent run; no per-assignee fan-out / inbox noise.
        assignee_ids := array[null::text];
      else
        assignee_ids := public.automation_resolve_assignees(tmpl.assignee, new_values, actor);
        -- Empty field/relation assignee → current user so the dialog still opens.
        if cardinality(assignee_ids) = 0 then
          assignee_ids := public.automation_resolve_assignees(
            '{"type":"currentUser"}'::jsonb,
            new_values,
            actor
          );
        end if;
        if cardinality(assignee_ids) = 0 then
          assignee_ids := array[null::text];
        end if;
      end if;

      template_snapshot := jsonb_build_object(
        'id', tmpl.id,
        'scenarioId', tmpl.scenario_id,
        'name', tmpl.name,
        'nameTemplate', tmpl.name_template,
        'description', tmpl.description,
        'triggerOptionId', tmpl.trigger_option_id,
        'stepOrder', tmpl.step_order,
        'isBlocking', tmpl.is_blocking,
        'kind', tmpl.kind,
        'launchConditions', tmpl.launch_conditions,
        'assignee', tmpl.assignee,
        'watchers', tmpl.watchers,
        'outcomes', tmpl.outcomes,
        'sla', tmpl.sla,
        'materials', tmpl.materials
      );

      task_name := public.automation_render_template(
        case
          when nullif(btrim(tmpl.name_template), '') is not null then tmpl.name_template
          else tmpl.name
        end,
        new_values
      );
      if nullif(btrim(task_name), '') is null then
        task_name := tmpl.name;
      end if;

      task_description := public.automation_render_template(
        coalesce(tmpl.description, ''),
        new_values
      );

      due := null;
      if tmpl.sla is not null and (tmpl.sla->>'hours') is not null then
        begin
          due := now() + ((tmpl.sla->>'hours')::numeric || ' hours')::interval;
        exception when others then
          due := null;
        end;
      end if;

      stored_option_id := coalesce(
        nullif(tmpl.trigger_option_id, ''),
        nullif(new_opt_id, ''),
        new_opt
      );

      foreach assignee_id in array assignee_ids
      loop
        task_id := 'atask-' || gen_random_uuid()::text;
        begin
          insert into public.automation_tasks (
            id, process_id, scenario_id, template_id,
            entity_id, record_id, trigger_field_id, trigger_option_id,
            assignee_user_id, status, is_blocking, step_order,
            name, description, config, due_at
          ) values (
            task_id,
            proc.id,
            scenario.id,
            tmpl.id,
            NEW.entity_id,
            NEW.id,
            proc.trigger_field_id,
            stored_option_id,
            assignee_id,
            'pending',
            tmpl.is_blocking,
            tmpl.step_order,
            task_name,
            task_description,
            template_snapshot,
            due
          );
        exception
          when unique_violation then
            continue;
          when others then
            raise warning 'automation spawn insert failed: %', sqlerrm;
            continue;
        end;

        if tmpl.kind = 'autofill' then
          -- First matching branch (empty conditions = else / always).
          autofill_outcome_id := null;
          for outcome_elem in
            select value
            from jsonb_array_elements(coalesce(tmpl.outcomes, '[]'::jsonb)) as value
          loop
            if public.automation_conditions_match(
              coalesce(
                outcome_elem->'conditions',
                '{"version":1,"match":"all","rules":[]}'::jsonb
              ),
              new_values,
              old_values
            ) then
              autofill_outcome_id := outcome_elem->>'id';
              exit;
            end if;
          end loop;
          if autofill_outcome_id is null then
            autofill_outcome_id := coalesce(tmpl.outcomes->0->>'id', '');
          end if;
          begin
            perform public.complete_automation_task(
              task_id,
              autofill_outcome_id,
              actor
            );
          exception when others then
            raise warning 'automation autofill complete failed: %', sqlerrm;
          end;
          -- No «assigned» notification for silent fills.
          continue;
        end if;

        begin
          for n_msg in
            select coalesce(nullif(r.message_template, ''), 'Назначена задача: ' || task_name)
            from public.automation_notification_rules r
            where r.template_id = tmpl.id
              and r.event = 'assigned'
          loop
            perform public.create_notification(
              coalesce(assignee_id, auth.uid()::text),
              'Назначена задача',
              n_msg,
              'automation',
              null,
              NEW.entity_id,
              NEW.id,
              task_id,
              true
            );
          end loop;
        exception when others then
          raise warning 'automation spawn notify failed: %', sqlerrm;
        end;
      end loop;
    end loop;
  end loop;

  return NEW;
end;
$$;
-- <<< END 20261016280000_automation_autofill_spawn.sql

-- >>> BEGIN 20261016290000_automation_autofill_client_complete.sql
-- Autofill: leave task pending so the client can complete it
-- (setField + «комм.» → вкладка «Записи» + rich actions). SQL still
-- picks the matching branch id into outcome_id for the client hint.

create or replace function public.automation_spawn_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := coalesce(OLD.field_values, '{}'::jsonb);
  new_values jsonb := coalesce(NEW.field_values, '{}'::jsonb);
  proc record;
  scenario record;
  tmpl record;
  old_opt text;
  new_opt text;
  old_opt_id text;
  new_opt_id text;
  assignee_ids text[];
  assignee_id text;
  task_id text;
  task_name text;
  task_description text;
  due timestamptz;
  template_snapshot jsonb;
  entered boolean;
  depth text;
  n_msg text;
  actor text;
  stored_option_id text;
  autofill_outcome_id text;
  outcome_elem jsonb;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = NEW.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    old_opt := coalesce(old_values->>proc.trigger_field_id, '');
    new_opt := coalesce(new_values->>proc.trigger_field_id, '');
    old_opt_id := coalesce((public.automation_field_ids(old_opt))[1], '');
    new_opt_id := coalesce((public.automation_field_ids(new_opt))[1], '');

    if TG_OP = 'UPDATE'
       and old_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_assert_no_blocking(
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        old_opt_id
      );
    end if;

    entered := false;
    if proc.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      entered := true;
    elsif proc.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      entered := old_values is distinct from new_values;
    elsif proc.trigger_kind in ('fieldEnter', 'fieldTransition') then
      entered := new_opt_id is distinct from old_opt_id and new_opt_id <> '';
    elsif proc.trigger_kind = 'fieldLeave' then
      entered := new_opt_id is distinct from old_opt_id and old_opt_id <> '';
    end if;

    if not entered then
      continue;
    end if;

    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, new_values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and (
          t.trigger_option_id = ''
          or t.trigger_option_id = new_opt
          or t.trigger_option_id = new_opt_id
          or t.trigger_option_id = any(public.automation_field_ids(new_opt))
        )
        and public.automation_conditions_match(t.launch_conditions, new_values, old_values)
    loop
      if tmpl.kind = 'autofill' then
        assignee_ids := array[null::text];
      else
        assignee_ids := public.automation_resolve_assignees(tmpl.assignee, new_values, actor);
        if cardinality(assignee_ids) = 0 then
          assignee_ids := public.automation_resolve_assignees(
            '{"type":"currentUser"}'::jsonb,
            new_values,
            actor
          );
        end if;
        if cardinality(assignee_ids) = 0 then
          assignee_ids := array[null::text];
        end if;
      end if;

      template_snapshot := jsonb_build_object(
        'id', tmpl.id,
        'scenarioId', tmpl.scenario_id,
        'name', tmpl.name,
        'nameTemplate', tmpl.name_template,
        'description', tmpl.description,
        'triggerOptionId', tmpl.trigger_option_id,
        'stepOrder', tmpl.step_order,
        'isBlocking', tmpl.is_blocking,
        'kind', tmpl.kind,
        'launchConditions', tmpl.launch_conditions,
        'assignee', tmpl.assignee,
        'watchers', tmpl.watchers,
        'outcomes', tmpl.outcomes,
        'sla', tmpl.sla,
        'materials', tmpl.materials
      );

      task_name := public.automation_render_template(
        case
          when nullif(btrim(tmpl.name_template), '') is not null then tmpl.name_template
          else tmpl.name
        end,
        new_values
      );
      if nullif(btrim(task_name), '') is null then
        task_name := tmpl.name;
      end if;

      task_description := public.automation_render_template(
        coalesce(tmpl.description, ''),
        new_values
      );

      due := null;
      if tmpl.sla is not null and (tmpl.sla->>'hours') is not null then
        begin
          due := now() + ((tmpl.sla->>'hours')::numeric || ' hours')::interval;
        exception when others then
          due := null;
        end;
      end if;

      stored_option_id := coalesce(
        nullif(tmpl.trigger_option_id, ''),
        nullif(new_opt_id, ''),
        new_opt
      );

      autofill_outcome_id := null;
      if tmpl.kind = 'autofill' then
        for outcome_elem in
          select value
          from jsonb_array_elements(coalesce(tmpl.outcomes, '[]'::jsonb)) as value
        loop
          if public.automation_conditions_match(
            coalesce(
              outcome_elem->'conditions',
              '{"version":1,"match":"all","rules":[]}'::jsonb
            ),
            new_values,
            old_values
          ) then
            autofill_outcome_id := outcome_elem->>'id';
            exit;
          end if;
        end loop;
        if autofill_outcome_id is null then
          autofill_outcome_id := coalesce(tmpl.outcomes->0->>'id', '');
        end if;
      end if;

      foreach assignee_id in array assignee_ids
      loop
        task_id := 'atask-' || gen_random_uuid()::text;
        begin
          insert into public.automation_tasks (
            id, process_id, scenario_id, template_id,
            entity_id, record_id, trigger_field_id, trigger_option_id,
            assignee_user_id, status, is_blocking, step_order,
            name, description, config, due_at, outcome_id
          ) values (
            task_id,
            proc.id,
            scenario.id,
            tmpl.id,
            NEW.entity_id,
            NEW.id,
            proc.trigger_field_id,
            stored_option_id,
            assignee_id,
            'pending',
            tmpl.is_blocking,
            tmpl.step_order,
            task_name,
            task_description,
            template_snapshot,
            due,
            autofill_outcome_id
          );
        exception
          when unique_violation then
            continue;
          when others then
            raise warning 'automation spawn insert failed: %', sqlerrm;
            continue;
        end;

        -- Autofill: no inbox noise; client completes (fields + comments).
        if tmpl.kind = 'autofill' then
          continue;
        end if;

        begin
          for n_msg in
            select coalesce(nullif(r.message_template, ''), 'Назначена задача: ' || task_name)
            from public.automation_notification_rules r
            where r.template_id = tmpl.id
              and r.event = 'assigned'
          loop
            perform public.create_notification(
              coalesce(assignee_id, auth.uid()::text),
              'Назначена задача',
              n_msg,
              'automation',
              null,
              NEW.entity_id,
              NEW.id,
              task_id,
              true
            );
          end loop;
        exception when others then
          raise warning 'automation spawn notify failed: %', sqlerrm;
        end;
      end loop;
    end loop;
  end loop;

  return NEW;
end;
$$;
-- <<< END 20261016290000_automation_autofill_client_complete.sql

-- >>> BEGIN 20261016300000_automation_launch_phase.sql
-- Launch phase: onEnter (after landing on stage) | beforeEnter (prep before
-- moving to the stage — spawn on previous stage / next-option / transition).

alter table public.automation_task_templates
  add column if not exists launch_phase text not null default 'onEnter';

alter table public.automation_task_templates
  drop constraint if exists automation_task_templates_launch_phase_check;

alter table public.automation_task_templates
  add constraint automation_task_templates_launch_phase_check
  check (launch_phase in ('onEnter', 'beforeEnter'));

create or replace function public.automation_spawn_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := coalesce(OLD.field_values, '{}'::jsonb);
  new_values jsonb := coalesce(NEW.field_values, '{}'::jsonb);
  proc record;
  scenario record;
  tmpl record;
  old_opt text;
  new_opt text;
  old_opt_id text;
  new_opt_id text;
  assignee_ids text[];
  assignee_id text;
  task_id text;
  task_name text;
  task_description text;
  due timestamptz;
  template_snapshot jsonb;
  entered boolean;
  depth text;
  n_msg text;
  actor text;
  stored_option_id text;
  autofill_outcome_id text;
  outcome_elem jsonb;
  launch_phase text;
  store_on_prev boolean;
  lands_on_target boolean;
  list_options jsonb;
  next_option_id text;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = NEW.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    old_opt := coalesce(old_values->>proc.trigger_field_id, '');
    new_opt := coalesce(new_values->>proc.trigger_field_id, '');
    old_opt_id := coalesce((public.automation_field_ids(old_opt))[1], '');
    new_opt_id := coalesce((public.automation_field_ids(new_opt))[1], '');

    if TG_OP = 'UPDATE'
       and old_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_assert_no_blocking(
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        old_opt_id
      );
    end if;

    entered := false;
    if proc.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      entered := true;
    elsif proc.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      entered := old_values is distinct from new_values;
    elsif proc.trigger_kind in ('fieldEnter', 'fieldTransition') then
      entered := new_opt_id is distinct from old_opt_id and new_opt_id <> '';
    elsif proc.trigger_kind = 'fieldLeave' then
      entered := new_opt_id is distinct from old_opt_id and old_opt_id <> '';
    end if;

    if not entered then
      continue;
    end if;

    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, new_values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    -- Next list option after the stage we just entered (for beforeEnter prep).
    next_option_id := null;
    select coalesce(
      (
        select f->'listOptions'
        from public.entities e
        cross join lateral jsonb_array_elements(
          coalesce(e.definition->'fields', '[]'::jsonb)
        ) as f
        where e.id = NEW.entity_id
          and f->>'id' = proc.trigger_field_id
        limit 1
      ),
      '[]'::jsonb
    ) into list_options;

    select opts.opt->>'id' into next_option_id
    from jsonb_array_elements(list_options) with ordinality as opts(opt, ord)
    where exists (
      select 1
      from jsonb_array_elements(list_options) with ordinality as cur(opt, ord)
      where coalesce(cur.opt->>'id', '') in (new_opt_id, new_opt)
        and cur.ord + 1 = opts.ord
    )
    limit 1;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and public.automation_conditions_match(t.launch_conditions, new_values, old_values)
        and (
          (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'onEnter'
            and (
              t.trigger_option_id = ''
              or t.trigger_option_id = new_opt
              or t.trigger_option_id = new_opt_id
              or t.trigger_option_id = any(public.automation_field_ids(new_opt))
            )
          )
          or (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
            and (
              t.trigger_option_id = new_opt
              or t.trigger_option_id = new_opt_id
              or t.trigger_option_id = any(public.automation_field_ids(new_opt))
              or (
                next_option_id is not null
                and t.trigger_option_id = next_option_id
              )
              or exists (
                select 1
                from jsonb_array_elements(
                  coalesce(scenario.stage_transitions, '[]'::jsonb)
                ) st
                where coalesce(st->>'fromOptionId', st->>'from_option_id', '')
                      in (new_opt_id, new_opt)
                  and coalesce(st->>'toOptionId', st->>'to_option_id', '')
                      = t.trigger_option_id
              )
            )
          )
        )
    loop
      launch_phase := coalesce(nullif(tmpl.launch_phase, ''), 'onEnter');
      lands_on_target :=
        tmpl.trigger_option_id = ''
        or tmpl.trigger_option_id = new_opt
        or tmpl.trigger_option_id = new_opt_id
        or tmpl.trigger_option_id = any(public.automation_field_ids(new_opt));
      store_on_prev := launch_phase = 'beforeEnter' and not lands_on_target;

      if tmpl.kind = 'autofill' then
        assignee_ids := array[null::text];
      else
        assignee_ids := public.automation_resolve_assignees(tmpl.assignee, new_values, actor);
        if cardinality(assignee_ids) = 0 then
          assignee_ids := public.automation_resolve_assignees(
            '{"type":"currentUser"}'::jsonb,
            new_values,
            actor
          );
        end if;
        if cardinality(assignee_ids) = 0 then
          assignee_ids := array[null::text];
        end if;
      end if;

      template_snapshot := jsonb_build_object(
        'id', tmpl.id,
        'scenarioId', tmpl.scenario_id,
        'name', tmpl.name,
        'nameTemplate', tmpl.name_template,
        'description', tmpl.description,
        'triggerOptionId', tmpl.trigger_option_id,
        'stepOrder', tmpl.step_order,
        'isBlocking', tmpl.is_blocking,
        'kind', tmpl.kind,
        'launchPhase', launch_phase,
        'launchConditions', tmpl.launch_conditions,
        'assignee', tmpl.assignee,
        'watchers', tmpl.watchers,
        'outcomes', tmpl.outcomes,
        'sla', tmpl.sla,
        'materials', tmpl.materials
      );

      task_name := public.automation_render_template(
        case
          when nullif(btrim(tmpl.name_template), '') is not null then tmpl.name_template
          else tmpl.name
        end,
        new_values
      );
      if nullif(btrim(task_name), '') is null then
        task_name := tmpl.name;
      end if;

      task_description := public.automation_render_template(
        coalesce(tmpl.description, ''),
        new_values
      );

      due := null;
      if tmpl.sla is not null and (tmpl.sla->>'hours') is not null then
        begin
          due := now() + ((tmpl.sla->>'hours')::numeric || ' hours')::interval;
        exception when others then
          due := null;
        end;
      end if;

      if store_on_prev then
        stored_option_id := coalesce(nullif(new_opt_id, ''), new_opt);
      else
        stored_option_id := coalesce(
          nullif(tmpl.trigger_option_id, ''),
          nullif(new_opt_id, ''),
          new_opt
        );
      end if;

      autofill_outcome_id := null;
      if tmpl.kind = 'autofill' then
        for outcome_elem in
          select value
          from jsonb_array_elements(coalesce(tmpl.outcomes, '[]'::jsonb)) as value
        loop
          if public.automation_conditions_match(
            coalesce(
              outcome_elem->'conditions',
              '{"version":1,"match":"all","rules":[]}'::jsonb
            ),
            new_values,
            old_values
          ) then
            autofill_outcome_id := outcome_elem->>'id';
            exit;
          end if;
        end loop;
        if autofill_outcome_id is null then
          autofill_outcome_id := coalesce(tmpl.outcomes->0->>'id', '');
        end if;
      end if;

      foreach assignee_id in array assignee_ids
      loop
        task_id := 'atask-' || gen_random_uuid()::text;
        begin
          insert into public.automation_tasks (
            id, process_id, scenario_id, template_id,
            entity_id, record_id, trigger_field_id, trigger_option_id,
            assignee_user_id, status, is_blocking, step_order,
            name, description, config, due_at, outcome_id
          ) values (
            task_id,
            proc.id,
            scenario.id,
            tmpl.id,
            NEW.entity_id,
            NEW.id,
            proc.trigger_field_id,
            stored_option_id,
            assignee_id,
            'pending',
            tmpl.is_blocking,
            tmpl.step_order,
            task_name,
            task_description,
            template_snapshot,
            due,
            autofill_outcome_id
          );
        exception
          when unique_violation then
            continue;
          when others then
            raise warning 'automation spawn insert failed: %', sqlerrm;
            continue;
        end;

        if tmpl.kind = 'autofill' then
          continue;
        end if;

        begin
          for n_msg in
            select coalesce(nullif(r.message_template, ''), 'Назначена задача: ' || task_name)
            from public.automation_notification_rules r
            where r.template_id = tmpl.id
              and r.event = 'assigned'
          loop
            perform public.create_notification(
              coalesce(assignee_id, auth.uid()::text),
              'Назначена задача',
              n_msg,
              'automation',
              null,
              NEW.entity_id,
              NEW.id,
              task_id,
              true
            );
          end loop;
        exception when others then
          raise warning 'automation spawn notify failed: %', sqlerrm;
        end;
      end loop;
    end loop;
  end loop;

  return NEW;
end;
$$;
-- <<< END 20261016300000_automation_launch_phase.sql

-- >>> BEGIN 20261016310000_automation_stage_transitions.sql
-- Conditional stage→stage gateways on the process map (edge between columns).

alter table public.automation_scenarios
  add column if not exists stage_transitions jsonb not null default '[]'::jsonb;

comment on column public.automation_scenarios.stage_transitions is
