-- >>> BEGIN 20261030180000_automation_notification_copy.sql
-- Cleaner automation notification copy:
-- title = task name, message = short status («Вам назначено» / …).
-- Always notify the assignee even when no custom rules exist.

create or replace function public.automation_notify_from_rules(
  p_template_id text,
  p_event text,
  p_values jsonb,
  p_old_values jsonb,
  p_actor text,
  p_title text,
  p_fallback_message text,
  p_entity_id text,
  p_record_id text,
  p_task_id text,
  p_fallback_user_id text default null
) returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  rule public.automation_notification_rules%rowtype;
  recipient_ids text[];
  recipient_id text;
  message text;
  title text;
  fallback_title text;
  fallback_message text;
  notified_ids text[] := array[]::text[];
  values jsonb := coalesce(p_values, '{}'::jsonb);
  old_values jsonb := coalesce(p_old_values, '{}'::jsonb);
  raw_title text := coalesce(nullif(btrim(p_title), ''), '');
  raw_fallback text := coalesce(nullif(btrim(p_fallback_message), ''), '');
  task_label text := null;
begin
  if p_template_id is null or btrim(p_template_id) = '' then
    return;
  end if;
  if p_event is null or btrim(p_event) = '' then
    return;
  end if;

  -- Extract task/record label from legacy «Назначена задача: …» fallbacks.
  if raw_fallback ~* '^(назначена|завершена|просрочена) задача:\s*.+$' then
    task_label := nullif(
      btrim(regexp_replace(raw_fallback, '^(назначена|завершена|просрочена) задача:\s*', '', 'i')),
      ''
    );
  elsif raw_title not in ('Назначена задача', 'Завершена задача', 'Просрочена задача', 'Уведомление', '')
    and raw_title !~* '^(назначена|завершена|просрочена) задача$'
  then
    task_label := raw_title;
  elsif raw_fallback <> ''
    and raw_fallback not in ('Назначена задача', 'Завершена задача', 'Просрочена задача')
    and raw_fallback !~* '^(назначена|завершена|просрочена) задача:\s*'
  then
    task_label := raw_fallback;
  end if;

  if p_event = 'assigned' then
    fallback_title := coalesce(task_label, nullif(raw_title, ''), 'Новая задача');
    fallback_message := 'Вам назначено';
  elsif p_event = 'completed' then
    fallback_title := coalesce(task_label, nullif(raw_title, ''), 'Задание');
    fallback_message := 'Задание выполнено';
  elsif p_event = 'overdue' then
    fallback_title := coalesce(task_label, nullif(raw_title, ''), 'Задание');
    fallback_message := 'Просрочено';
  else
    fallback_title := coalesce(nullif(raw_title, ''), 'Уведомление');
    fallback_message := coalesce(nullif(raw_fallback, ''), fallback_title);
  end if;

  for rule in
    select *
    from public.automation_notification_rules r
    where r.template_id = p_template_id
      and r.event = p_event
  loop
    if not public.automation_conditions_match(
      coalesce(
        rule.conditions,
        '{"version":1,"match":"all","rules":[]}'::jsonb
      ),
      values,
      old_values
    ) then
      continue;
    end if;

    recipient_ids := public.automation_resolve_assignees(
      coalesce(rule.recipients, '{"type":"currentUser"}'::jsonb),
      values,
      nullif(btrim(coalesce(p_actor, '')), '')
    );

    if cardinality(recipient_ids) = 0
       and nullif(btrim(coalesce(p_fallback_user_id, '')), '') is not null
    then
      recipient_ids := array[p_fallback_user_id];
    end if;

    if cardinality(recipient_ids) = 0 then
      continue;
    end if;

    message := public.automation_render_template(
      coalesce(rule.message_template, ''),
      values
    );
    if nullif(btrim(message), '') is null then
      message := fallback_message;
    end if;
    title := fallback_title;

    foreach recipient_id in array recipient_ids
    loop
      if nullif(btrim(coalesce(recipient_id, '')), '') is null then
        continue;
      end if;
      perform public.create_notification(
        recipient_id,
        title,
        message,
        'automation',
        null,
        p_entity_id,
        p_record_id,
        p_task_id,
        true
      );
      if not (recipient_id = any (notified_ids)) then
        notified_ids := array_append(notified_ids, recipient_id);
      end if;
    end loop;
  end loop;

  -- Assignee always gets a clean default when not covered by a custom rule.
  if nullif(btrim(coalesce(p_fallback_user_id, '')), '') is not null
     and not (p_fallback_user_id = any (notified_ids))
  then
    perform public.create_notification(
      p_fallback_user_id,
      fallback_title,
      fallback_message,
      'automation',
      null,
      p_entity_id,
      p_record_id,
      p_task_id,
      true
    );
  end if;
end;
$$;
-- <<< END 20261030180000_automation_notification_copy.sql

-- >>> BEGIN 20261030190000_notification_template_labels.sql
-- Render notification / automation templates with human labels:
-- relation → record name, list → option name, strip unresolved {{field-…}}.

create or replace function public.entity_record_display_name(p_record_id text)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rid text := nullif(btrim(coalesce(p_record_id, '')), '');
  ent_id text;
  def jsonb;
  field jsonb;
  name_field_id text;
  label text;
begin
  if rid is null then
    return null;
  end if;

  select er.entity_id, e.definition
  into ent_id, def
  from public.entity_records er
  join public.entities e on e.id = er.entity_id
  where er.id = rid
  limit 1;

  if ent_id is null then
    return null;
  end if;

  -- Prefer locked name field, then «Название».
  for field in
    select *
    from jsonb_array_elements(coalesce(def->'fields', '[]'::jsonb))
  loop
    if coalesce((field->>'locked')::boolean, false)
       or lower(coalesce(field->>'name', '')) in ('название', 'name')
    then
      name_field_id := nullif(btrim(coalesce(field->>'id', '')), '');
      exit;
    end if;
  end loop;

  if name_field_id is null then
    return null;
  end if;

  select nullif(btrim(coalesce(er.field_values->>name_field_id, '')), '')
  into label
  from public.entity_records er
  where er.id = rid;

  if label is null or label = 'Без названия' then
    return null;
  end if;
  -- Avoid returning another raw record id as a «name».
  if label ~* '^(record-|user-)[0-9a-f-]{8,}$' then
    return coalesce(public.entity_record_display_name(label), label);
  end if;
  return label;
end;
$$;

create or replace function public.entity_format_field_value(
  p_entity_id text,
  p_field_id text,
  p_raw text
)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  raw text := coalesce(p_raw, '');
  def jsonb;
  field jsonb;
  field_type text;
  target_id text;
  opt jsonb;
  ids text[];
  id text;
  labels text[] := array[]::text[];
  label text;
  parsed jsonb;
begin
  if nullif(btrim(raw), '') is null then
    return '';
  end if;

  select e.definition into def
  from public.entities e
  where e.id = p_entity_id
  limit 1;

  if def is not null and nullif(btrim(coalesce(p_field_id, '')), '') is not null then
    select f into field
    from jsonb_array_elements(coalesce(def->'fields', '[]'::jsonb)) as f
    where f->>'id' = p_field_id
    limit 1;

    if field is not null then
      field_type := coalesce(field->>'type', '');
      target_id := nullif(btrim(coalesce(field->>'relationEntityId', '')), '');

      if field_type = 'list' then
        -- Single or multi list values.
        ids := array[]::text[];
        if left(btrim(raw), 1) = '[' then
          begin
            parsed := raw::jsonb;
            if jsonb_typeof(parsed) = 'array' then
              select coalesce(array_agg(x), array[]::text[])
              into ids
              from jsonb_array_elements_text(parsed) as t(x);
            end if;
          exception when others then
            ids := string_to_array(raw, ',');
          end;
        else
          ids := string_to_array(raw, ',');
        end if;

        foreach id in array ids
        loop
          id := nullif(btrim(id), '');
          if id is null then
            continue;
          end if;
          if id like '__other__:%' then
            labels := array_append(labels, substr(id, length('__other__:') + 1));
            continue;
          end if;
          label := null;
          for opt in
            select *
            from jsonb_array_elements(coalesce(field->'listOptions', '[]'::jsonb))
          loop
            if opt->>'id' = id then
              label := nullif(btrim(coalesce(opt->>'name', '')), '');
              exit;
            end if;
          end loop;
          labels := array_append(labels, coalesce(label, id));
        end loop;
        return array_to_string(labels, ', ');
      end if;

      if field_type in ('relation', 'belonging', 'users', 'dependencies')
         or target_id is not null
      then
        ids := array[]::text[];
        if left(btrim(raw), 1) = '[' then
          begin
            parsed := raw::jsonb;
            if jsonb_typeof(parsed) = 'array' then
              select coalesce(array_agg(x), array[]::text[])
              into ids
              from jsonb_array_elements_text(parsed) as t(x);
            end if;
          exception when others then
            ids := string_to_array(raw, ',');
          end;
        else
          ids := string_to_array(raw, ',');
        end if;

        foreach id in array ids
        loop
          id := nullif(btrim(id), '');
          if id is null then
            continue;
          end if;
          label := public.entity_record_display_name(id);
          labels := array_append(labels, coalesce(label, id));
        end loop;
        return array_to_string(labels, ', ');
      end if;
    end if;
  end if;

  -- Fallback: bare record id → display name.
  if raw ~* '^(record-|user-)[0-9a-f-]{8,}$' then
    return coalesce(public.entity_record_display_name(raw), raw);
  end if;

  if left(btrim(raw), 1) = '[' then
    begin
      parsed := raw::jsonb;
      if jsonb_typeof(parsed) = 'array' then
        select coalesce(array_agg(coalesce(public.entity_record_display_name(x), x)), array[]::text[])
        into labels
        from jsonb_array_elements_text(parsed) as t(x);
        return array_to_string(labels, ', ');
      end if;
    exception when others then
      null;
    end;
  end if;

  return raw;
end;
$$;

create or replace function public.entity_replace_record_ids_in_text(p_text text)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result text := coalesce(p_text, '');
  m text[];
  piece text;
  resolved text;
  pos int;
  after_text text;
  guard int := 0;
begin
  loop
    guard := guard + 1;
    exit when guard > 32;
    m := regexp_match(result, '((?:record-|user-)[0-9a-fA-F-]{8,})');
    exit when m is null;
    piece := m[1];
    pos := position(piece in result);
    after_text := substr(result, pos + length(piece));
    -- Trim one leading space when comparing the following text.
    if left(after_text, 1) = ' ' then
      after_text := substr(after_text, 2);
    end if;
    resolved := public.entity_record_display_name(piece);
    if resolved is null or resolved = '' then
      result := replace(result, piece, '');
    elsif lower(left(after_text, length(resolved))) = lower(resolved) then
      -- «record-… Same Name…» → drop the id, keep the existing name.
      result := replace(result, piece, '');
    else
      result := replace(result, piece, resolved);
    end if;
  end loop;
  result := regexp_replace(result, '\s{2,}', ' ', 'g');
  return btrim(result);
end;
$$;

-- Drop earlier 2-arg overload to avoid ambiguous (text, jsonb) calls.
drop function if exists public.notification_render_template(text, jsonb);
create or replace function public.notification_render_template(
  p_template text,
  p_values jsonb,
  p_entity_id text default null
) returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result text := coalesce(p_template, '');
  m text[];
  token text;
  field_id text;
  raw text;
  label text;
begin
  if result = '' then
    return result;
  end if;

  -- Replace placeholders found in the template (not only keys present in values).
  for m in
    select regexp_matches(result, '\{\{([^}]+)\}\}', 'g')
  loop
    field_id := nullif(btrim(coalesce(m[1], '')), '');
    if field_id is null then
      continue;
    end if;
    token := '{{' || field_id || '}}';
    raw := coalesce(p_values->>field_id, '');
    label := public.entity_format_field_value(p_entity_id, field_id, raw);
    result := replace(result, token, coalesce(label, ''));
  end loop;

  -- Drop any leftover tokens, resolve bare record ids, tidy whitespace.
  result := regexp_replace(result, '\{\{[^}]+\}\}', '', 'g');
  result := public.entity_replace_record_ids_in_text(result);
  result := regexp_replace(result, '[ \t]{2,}', ' ', 'g');
  result := regexp_replace(result, ' ?([,;:])', '\1', 'g');
  return btrim(result);
end;
$$;

-- Keep automation_render_template signature; add optional entity id for labels.
-- Drop the earlier 2-arg overload first: CREATE OR REPLACE with a defaulted
-- 3rd arg does not replace (text, jsonb), and two-arg calls become ambiguous.
drop function if exists public.automation_render_template(text, jsonb);
create or replace function public.automation_render_template(
  p_template text,
  p_values jsonb,
  p_entity_id text default null
)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  return public.notification_render_template(p_template, p_values, p_entity_id);
end;
$$;

-- Entity notification rules: pass entity id into renderer.
create or replace function public.notification_dispatch_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := coalesce(OLD.field_values, '{}'::jsonb);
  new_values jsonb := coalesce(NEW.field_values, '{}'::jsonb);
  rule record;
  matched boolean;
  old_opt text;
  new_opt text;
  recipient_ids text[];
  recipient_id text;
  title text;
  message text;
  depth text;
  actor text;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  actor := coalesce(auth.uid()::text, '');

  for rule in
    select *
    from public.notification_rules r
    where r.enabled = true
      and r.entity_id = NEW.entity_id
  loop
    matched := false;
    old_opt := '';
    new_opt := '';

    if rule.field_id <> '' then
      old_opt := coalesce(old_values->>rule.field_id, '');
      new_opt := coalesce(new_values->>rule.field_id, '');
    end if;

    if rule.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      matched := true;
    elsif rule.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      matched := old_values is distinct from new_values;
    elsif rule.trigger_kind = 'fieldEnter' and TG_OP in ('INSERT', 'UPDATE') then
      matched :=
        new_opt is distinct from old_opt
        and new_opt <> ''
        and (
          rule.option_id = ''
          or rule.option_id = new_opt
          or rule.option_id = any(public.automation_field_ids(new_opt))
        );
    elsif rule.trigger_kind = 'fieldLeave' and TG_OP = 'UPDATE' then
      matched :=
        new_opt is distinct from old_opt
        and old_opt <> ''
        and (
          rule.option_id = ''
          or rule.option_id = old_opt
          or rule.option_id = any(public.automation_field_ids(old_opt))
        );
    elsif rule.trigger_kind = 'fieldTransition' and TG_OP = 'UPDATE' then
      matched :=
        new_opt is distinct from old_opt
        and (
          rule.from_option_id = ''
          or rule.from_option_id = old_opt
          or rule.from_option_id = any(public.automation_field_ids(old_opt))
        )
        and (
          rule.to_option_id = ''
          or rule.to_option_id = new_opt
          or rule.to_option_id = any(public.automation_field_ids(new_opt))
        );
    end if;

    if not matched then
      continue;
    end if;

    if not public.automation_conditions_match(rule.conditions, new_values, old_values) then
      continue;
    end if;

    recipient_ids := public.automation_resolve_assignees(
      rule.recipients,
      new_values,
      nullif(actor, '')
    );

    if cardinality(recipient_ids) = 0 and actor <> '' then
      recipient_ids := array[actor];
    end if;

    title := public.notification_render_template(
      rule.title_template,
      new_values,
      NEW.entity_id
    );
    message := public.notification_render_template(
      rule.message_template,
      new_values,
      NEW.entity_id
    );
    if nullif(btrim(title), '') is null then
      title := coalesce(nullif(btrim(rule.name), ''), 'Уведомление');
    end if;
    if nullif(btrim(message), '') is null then
      message := title;
    end if;

    foreach recipient_id in array recipient_ids
    loop
      perform public.create_notification(
        recipient_id,
        title,
        message,
        'rule',
        rule.id,
        NEW.entity_id,
        NEW.id,
        null,
        rule.show_toast
      );
    end loop;
  end loop;

  return NEW;
end;
$$;

-- Automation notify rules: render with entity labels.
create or replace function public.automation_notify_from_rules(
  p_template_id text,
  p_event text,
  p_values jsonb,
  p_old_values jsonb,
  p_actor text,
  p_title text,
  p_fallback_message text,
  p_entity_id text,
  p_record_id text,
  p_task_id text,
  p_fallback_user_id text default null
) returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  rule public.automation_notification_rules%rowtype;
  recipient_ids text[];
  recipient_id text;
  message text;
  title text;
  fallback_title text;
  fallback_message text;
  notified_ids text[] := array[]::text[];
  values jsonb := coalesce(p_values, '{}'::jsonb);
  old_values jsonb := coalesce(p_old_values, '{}'::jsonb);
  raw_title text := coalesce(nullif(btrim(p_title), ''), '');
  raw_fallback text := coalesce(nullif(btrim(p_fallback_message), ''), '');
  task_label text := null;
begin
  if p_template_id is null or btrim(p_template_id) = '' then
    return;
  end if;
  if p_event is null or btrim(p_event) = '' then
    return;
  end if;

  if raw_fallback ~* '^(назначена|завершена|просрочена) задача:\s*.+$' then
    task_label := nullif(
      btrim(regexp_replace(raw_fallback, '^(назначена|завершена|просрочена) задача:\s*', '', 'i')),
      ''
    );
  elsif raw_title not in ('Назначена задача', 'Завершена задача', 'Просрочена задача', 'Уведомление', '')
    and raw_title !~* '^(назначена|завершена|просрочена) задача$'
  then
    task_label := raw_title;
  elsif raw_fallback <> ''
    and raw_fallback not in ('Назначена задача', 'Завершена задача', 'Просрочена задача')
    and raw_fallback !~* '^(назначена|завершена|просрочена) задача:\s*'
  then
    task_label := raw_fallback;
  end if;

  if task_label is not null then
    task_label := public.entity_replace_record_ids_in_text(task_label);
  end if;

  if p_event = 'assigned' then
    fallback_title := coalesce(nullif(task_label, ''), nullif(raw_title, ''), 'Новая задача');
    fallback_message := 'Вам назначено';
  elsif p_event = 'completed' then
    fallback_title := coalesce(nullif(task_label, ''), nullif(raw_title, ''), 'Задание');
    fallback_message := 'Задание выполнено';
  elsif p_event = 'overdue' then
    fallback_title := coalesce(nullif(task_label, ''), nullif(raw_title, ''), 'Задание');
    fallback_message := 'Просрочено';
  else
    fallback_title := coalesce(nullif(raw_title, ''), 'Уведомление');
    fallback_message := coalesce(nullif(raw_fallback, ''), fallback_title);
  end if;

  fallback_title := public.entity_replace_record_ids_in_text(fallback_title);
  fallback_message := public.entity_replace_record_ids_in_text(fallback_message);

  for rule in
    select *
    from public.automation_notification_rules r
    where r.template_id = p_template_id
      and r.event = p_event
  loop
    if not public.automation_conditions_match(
      coalesce(
        rule.conditions,
        '{"version":1,"match":"all","rules":[]}'::jsonb
      ),
      values,
      old_values
    ) then
      continue;
    end if;

    recipient_ids := public.automation_resolve_assignees(
      coalesce(rule.recipients, '{"type":"currentUser"}'::jsonb),
      values,
      nullif(btrim(coalesce(p_actor, '')), '')
    );

    if cardinality(recipient_ids) = 0
       and nullif(btrim(coalesce(p_fallback_user_id, '')), '') is not null
    then
      recipient_ids := array[p_fallback_user_id];
    end if;

    if cardinality(recipient_ids) = 0 then
      continue;
    end if;

    message := public.automation_render_template(
      coalesce(rule.message_template, ''),
      values,
      p_entity_id
    );
    message := public.entity_replace_record_ids_in_text(message);
    if nullif(btrim(message), '') is null then
      message := fallback_message;
    end if;
    title := fallback_title;

    foreach recipient_id in array recipient_ids
    loop
      if nullif(btrim(coalesce(recipient_id, '')), '') is null then
        continue;
      end if;
      perform public.create_notification(
        recipient_id,
        title,
        message,
        'automation',
        null,
        p_entity_id,
        p_record_id,
        p_task_id,
        true
      );
      if not (recipient_id = any (notified_ids)) then
        notified_ids := array_append(notified_ids, recipient_id);
      end if;
    end loop;
  end loop;

  if nullif(btrim(coalesce(p_fallback_user_id, '')), '') is not null
     and not (p_fallback_user_id = any (notified_ids))
  then
    perform public.create_notification(
      p_fallback_user_id,
      fallback_title,
      fallback_message,
      'automation',
      null,
      p_entity_id,
      p_record_id,
      p_task_id,
      true
    );
  end if;
end;
$$;
-- <<< END 20261030190000_notification_template_labels.sql

-- >>> BEGIN 20261031120000_automation_no_next_option_before_enter_prep.sql
-- Fix premature sequential / beforeEnter release across stages.
--
-- Root cause (Lead «ГИП» + ТКП overlap):
-- 1) automation_spawn_on_record_change used «next kanban list option» to
--    spawn beforeEnter of stage N+1 when landing on stage N (ТКП «Создано»).
-- 2) Completing that silent beforeEnter called automation_spawn_next_sequential_task
--    which crossed beforeEnter → onEnter of N+1 even while the record stayed
--    on N — opening «Выбрать руководителей…» while Lead «Ознакомиться с ТЗ»
--    was still pending.
--
-- Also harden sequential enter-spawn: when several templates share step_order,
-- only the first by (step_order, created_at, id) spawns; later ones wait for
-- complete → spawn_next.
--
-- Cross-stage beforeEnter prep stays available via:
--   • explicit scenario.stage_transitions
--   • automation_ensure_before_enter_prep (manual move)
-- Same-stage beforeEnter on land is unchanged.

create or replace function public.automation_spawn_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := '{}'::jsonb;
  new_values jsonb := '{}'::jsonb;
  proc public.automation_processes%rowtype;
  scenario public.automation_scenarios%rowtype;
  tmpl public.automation_task_templates%rowtype;
  old_opt text;
  new_opt text;
  old_opt_id text;
  new_opt_id text;
  entered boolean;
  depth text;
  actor text;
  stored_option_id text;
  v_launch_phase text;
  store_on_prev boolean;
  is_prep_from_prev boolean;
  release_mode text;
  has_earlier boolean;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  if TG_OP <> 'INSERT' then
    old_values := coalesce(OLD.field_values, '{}'::jsonb);
  end if;
  if TG_OP <> 'DELETE' then
    new_values := coalesce(NEW.field_values, '{}'::jsonb);
  end if;

  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = NEW.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    old_opt := coalesce(old_values->>proc.trigger_field_id, '');
    new_opt := coalesce(new_values->>proc.trigger_field_id, '');
    old_opt_id := coalesce((public.automation_field_ids(old_opt))[1], '');
    new_opt_id := coalesce((public.automation_field_ids(new_opt))[1], '');

    if TG_OP = 'UPDATE'
       and old_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_assert_no_blocking(
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        old_opt_id
      );
    end if;

    entered := false;
    if proc.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      entered := true;
    elsif proc.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      entered := old_values is distinct from new_values;
    elsif proc.trigger_kind in ('fieldEnter', 'fieldTransition') then
      entered := new_opt_id is distinct from old_opt_id and new_opt_id <> '';
    elsif proc.trigger_kind = 'fieldLeave' then
      entered := new_opt_id is distinct from old_opt_id and old_opt_id <> '';
    end if;

    if not entered then
      continue;
    end if;

    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, new_values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by (
          select count(*)::int
          from public.automation_task_templates t
          where t.scenario_id = s.id
            and coalesce(t.enabled, true) = true
        ) desc,
        s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and coalesce(t.enabled, true) = true
        and public.automation_conditions_match(t.launch_conditions, new_values, old_values)
        and (
          (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'onEnter'
            and (
              t.trigger_option_id = ''
              or t.trigger_option_id = new_opt
              or t.trigger_option_id = new_opt_id
              or t.trigger_option_id = any(public.automation_field_ids(new_opt))
            )
          )
          or (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
            and (
              exists (
                select 1
                from jsonb_array_elements(
                  coalesce(scenario.stage_transitions, '[]'::jsonb)
                ) st
                where coalesce(st->>'fromOptionId', st->>'from_option_id', '')
                      in (new_opt_id, new_opt)
                  and coalesce(st->>'toOptionId', st->>'to_option_id', '')
                      = t.trigger_option_id
              )
              or (
                (
                  t.trigger_option_id = new_opt
                  or t.trigger_option_id = new_opt_id
                  or t.trigger_option_id = any(public.automation_field_ids(new_opt))
                )
                and not exists (
                  select 1
                  from public.automation_tasks existing
                  where existing.record_id = NEW.id
                    and existing.template_id = t.id
                    and existing.status in ('pending', 'returned', 'completed')
                )
              )
            )
          )
        )
      order by
        case
          when coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
            then 0
          else 1
        end,
        t.step_order asc,
        t.created_at asc,
        t.id asc
    loop
      v_launch_phase := coalesce(nullif(tmpl.launch_phase, ''), 'onEnter');

      is_prep_from_prev :=
        v_launch_phase = 'beforeEnter'
        and exists (
          select 1
          from jsonb_array_elements(
            coalesce(scenario.stage_transitions, '[]'::jsonb)
          ) st
          where coalesce(st->>'fromOptionId', st->>'from_option_id', '')
                in (new_opt_id, new_opt)
            and coalesce(st->>'toOptionId', st->>'to_option_id', '')
                = tmpl.trigger_option_id
        );

      store_on_prev := is_prep_from_prev;

      release_mode := coalesce(
        nullif(scenario.stage_task_release->>tmpl.trigger_option_id, ''),
        'parallel'
      );

      if release_mode = 'sequential' then
        -- Only the first sibling by (step_order, created_at, id) spawns now.
        select exists (
          select 1
          from public.automation_task_templates earlier
          where earlier.scenario_id = scenario.id
            and coalesce(earlier.enabled, true) = true
            and earlier.trigger_option_id = tmpl.trigger_option_id
            and coalesce(nullif(earlier.launch_phase, ''), 'onEnter') = v_launch_phase
            and (
              earlier.step_order < tmpl.step_order
              or (
                earlier.step_order = tmpl.step_order
                and (
                  earlier.created_at < tmpl.created_at
                  or (
                    earlier.created_at = tmpl.created_at
                    and earlier.id < tmpl.id
                  )
                )
              )
            )
            and public.automation_conditions_match(
              earlier.launch_conditions,
              new_values,
              old_values
            )
        ) into has_earlier;
        if has_earlier then
          continue;
        end if;

        -- onEnter vs beforeEnter of the same stage:
        -- • interactive beforeEnter → must be completed
        -- • silent beforeEnter (autofill/actions) → must be spawned only
        --   (client completes it; waiting for complete hid the interactive task)
        if v_launch_phase = 'onEnter' then
          select exists (
            select 1
            from public.automation_task_templates be
            where be.scenario_id = scenario.id
              and coalesce(be.enabled, true) = true
              and be.trigger_option_id = tmpl.trigger_option_id
              and coalesce(nullif(be.launch_phase, ''), 'onEnter') = 'beforeEnter'
              and public.automation_conditions_match(
                be.launch_conditions,
                new_values,
                old_values
              )
              and (
                (
                  be.kind not in ('autofill', 'actions')
                  and not exists (
                    select 1
                    from public.automation_tasks done
                    where done.record_id = NEW.id
                      and done.template_id = be.id
                      and done.status = 'completed'
                  )
                )
                or (
                  be.kind in ('autofill', 'actions')
                  and not exists (
                    select 1
                    from public.automation_tasks spawned
                    where spawned.record_id = NEW.id
                      and spawned.template_id = be.id
                      and spawned.status in ('pending', 'returned', 'completed')
                  )
                )
              )
          ) into has_earlier;
          if has_earlier then
            continue;
          end if;
        end if;
      end if;

      if store_on_prev then
        stored_option_id := coalesce(nullif(new_opt_id, ''), new_opt);
      else
        stored_option_id := coalesce(
          nullif(tmpl.trigger_option_id, ''),
          nullif(new_opt_id, ''),
          new_opt
        );
      end if;

      perform public.automation_spawn_template_for_record(
        tmpl,
        proc.id,
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        stored_option_id,
        new_values,
        old_values,
        actor
      );
    end loop;
  end loop;

  return NEW;
end;
$$;

-- Do not unlock onEnter of stage N while the record is still on N-1
-- (prep-from-prev / next-option beforeEnter residue).
create or replace function public.automation_spawn_next_sequential_task(
  p_task public.automation_tasks,
  p_actor text default null
) returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  scenario public.automation_scenarios%rowtype;
  rec public.entity_records%rowtype;
  release_mode text;
  stage_option_id text;
  v_launch_phase text;
  next_tmpl public.automation_task_templates%rowtype;
  values jsonb;
  stored_option_id text;
  already_spawned boolean;
  siblings_pending boolean;
  complete_when text;
  current_stage text;
  tmpl_created_at timestamptz;
  tmpl_id text;
begin
  select * into scenario
  from public.automation_scenarios
  where id = p_task.scenario_id;
  if scenario.id is null then
    return null;
  end if;

  stage_option_id := coalesce(
    nullif(p_task.config->>'triggerOptionId', ''),
    nullif(p_task.trigger_option_id, '')
  );
  if stage_option_id is null or stage_option_id = '' then
    return null;
  end if;

  release_mode := coalesce(
    nullif(scenario.stage_task_release->>stage_option_id, ''),
    'parallel'
  );
  if release_mode <> 'sequential' then
    return null;
  end if;

  complete_when := lower(coalesce(
    nullif(btrim(coalesce(p_task.config->'assignee'->>'completeWhen', '')), ''),
    nullif(btrim(coalesce(p_task.config->'assignee'->>'complete_when', '')), ''),
    'all'
  ));

  -- AND-join when completeWhen = all (default). Skip for «any».
  if nullif(trim(coalesce(p_task.template_id, '')), '') is not null
     and complete_when <> 'any'
  then
    select exists (
      select 1
      from public.automation_tasks sibling
      where sibling.record_id = p_task.record_id
        and sibling.template_id = p_task.template_id
        and sibling.process_id is not distinct from p_task.process_id
        and sibling.id <> p_task.id
        and sibling.status in ('pending', 'returned')
    ) into siblings_pending;
    if siblings_pending then
      return null;
    end if;
  end if;

  v_launch_phase := coalesce(
    nullif(p_task.config->>'launchPhase', ''),
    'onEnter'
  );

  select * into rec from public.entity_records where id = p_task.record_id;
  if rec.id is null then
    return null;
  end if;
  values := coalesce(rec.field_values, '{}'::jsonb);

  tmpl_id := coalesce(nullif(p_task.template_id, ''), '');
  select t.created_at into tmpl_created_at
  from public.automation_task_templates t
  where t.id = tmpl_id;
  tmpl_created_at := coalesce(tmpl_created_at, p_task.created_at, '-infinity'::timestamptz);

  -- Same phase: immediate next by (step_order, created_at, id).
  select * into next_tmpl
  from public.automation_task_templates t
  where t.scenario_id = p_task.scenario_id
    and coalesce(t.enabled, true) = true
    and t.trigger_option_id = stage_option_id
    and coalesce(nullif(t.launch_phase, ''), 'onEnter') = v_launch_phase
    and (
      t.step_order > p_task.step_order
      or (
        t.step_order = p_task.step_order
        and (
          t.created_at > tmpl_created_at
          or (t.created_at = tmpl_created_at and t.id > tmpl_id)
        )
      )
    )
    and public.automation_conditions_match(
      t.launch_conditions,
      values,
      values
    )
  order by t.step_order asc, t.created_at asc, t.id asc
  limit 1;

  -- Cross beforeEnter → first onEnter only when the record has landed on
  -- this stage. Prep stored on the previous stage must not unlock onEnter.
  if next_tmpl.id is null and v_launch_phase = 'beforeEnter' then
    current_stage := coalesce(
      (public.automation_field_ids(values->>p_task.trigger_field_id))[1],
      nullif(values->>p_task.trigger_field_id, ''),
      ''
    );
    if current_stage = stage_option_id then
      select * into next_tmpl
      from public.automation_task_templates t
      where t.scenario_id = p_task.scenario_id
        and coalesce(t.enabled, true) = true
        and t.trigger_option_id = stage_option_id
        and coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'onEnter'
        and public.automation_conditions_match(
          t.launch_conditions,
          values,
          values
        )
      order by t.step_order asc, t.created_at asc, t.id asc
      limit 1;
    end if;
  end if;

  if next_tmpl.id is null then
    return null;
  end if;

  select exists (
    select 1
    from public.automation_tasks existing
    where existing.record_id = p_task.record_id
      and existing.template_id = next_tmpl.id
      and existing.status in ('pending', 'returned', 'completed')
  ) into already_spawned;

  if already_spawned then
    return null;
  end if;

  stored_option_id := coalesce(
    nullif(btrim(next_tmpl.trigger_option_id), ''),
    stage_option_id,
    p_task.trigger_option_id
  );

  return public.automation_spawn_template_for_record(
    next_tmpl,
    p_task.process_id,
    p_task.entity_id,
    p_task.record_id,
    p_task.trigger_field_id,
    stored_option_id,
    values,
    values,
    p_actor
  );
end;
$$;

grant execute on function public.automation_spawn_next_sequential_task(
  public.automation_tasks,
  text
) to authenticated, service_role;

-- Live/config alignment: ТКП «Автосоздание задач отделов» must run onEnter of
-- «Выбор отделов» (not beforeEnter prep), after Lead advances the stage.
update public.automation_task_templates
set
  launch_phase = 'onEnter',
  step_order = 0,
  updated_at = now()
where id = 'atpl-edf9b197-ec40-4308-8a05-5c8ea6772b93';

update public.automation_task_templates
set
  launch_phase = 'onEnter',
  step_order = 1,
  updated_at = now()
where id = 'atpl-01b8793a-1fcf-4b42-9b3a-b237b5ee3e9e';
-- <<< END 20261031120000_automation_no_next_option_before_enter_prep.sql

-- >>> BEGIN 20261031140000_tkp_stage_default_created.sql
-- «Разбор ТКП».«Стадия» default must be «Создано», not «Выбор отделов».
-- Otherwise Lead createRecord lands on «Выбор отделов» and immediately spawns
-- «Выбрать руководителей» while Lead «Ознакомиться с ТЗ» is still open.

update public.entities e
set
  definition = jsonb_set(
    e.definition,
    array['fields', idx.ordinal::text, 'defaultValue'],
    jsonb_build_object(
      'kind', 'value',
      'value', 'list-f0e5e1c4-3702-4680-bbeb-222e35edb8f3'
    ),
    true
  ),
  updated_at = now()
from (
  select
    (ord - 1) as ordinal
  from public.entities e2
  cross join lateral jsonb_array_elements(
    coalesce(e2.definition->'fields', '[]'::jsonb)
  ) with ordinality as f(field, ord)
  where e2.id = 'entity-d5de40cb-617e-40dd-834a-e9895a432898'
    and f.field->>'id' = 'field-b1da7b05-3eb6-4bc0-87a7-1de79068749b'
  limit 1
) as idx
where e.id = 'entity-d5de40cb-617e-40dd-834a-e9895a432898';

-- Keep published schema snapshot aligned when present.
update public.entity_schema_versions v
set
  definition = jsonb_set(
    v.definition,
    array['fields', idx.ordinal::text, 'defaultValue'],
    jsonb_build_object(
      'kind', 'value',
      'value', 'list-f0e5e1c4-3702-4680-bbeb-222e35edb8f3'
    ),
    true
  )
from (
  select
    v2.id as version_id,
    (ord - 1) as ordinal
  from public.entity_schema_versions v2
  cross join lateral jsonb_array_elements(
    coalesce(v2.definition->'fields', '[]'::jsonb)
  ) with ordinality as f(field, ord)
  where v2.entity_id = 'entity-d5de40cb-617e-40dd-834a-e9895a432898'
    and v2.version = (
      select max(v3.version)
      from public.entity_schema_versions v3
      where v3.entity_id = 'entity-d5de40cb-617e-40dd-834a-e9895a432898'
    )
    and f.field->>'id' = 'field-b1da7b05-3eb6-4bc0-87a7-1de79068749b'
  limit 1
) as idx
where v.id = idx.version_id;
-- <<< END 20261031140000_tkp_stage_default_created.sql

-- >>> BEGIN 20261031160000_automation_resolve_user_leaf_fallback.sql
-- relatedField hop may land on Users rows when «Стадия/отделы» nested slots
-- were filled with managers instead of department catalog ids. Reading
-- Отдел.Руководители on those rows is empty — treat the user record id as the
-- assignee. Also fall back to a catalog «Руководитель(и)» field by name when
-- the configured fieldId is missing on the landed entity.

create or replace function public.automation_resolve_assignees(
  resolver jsonb,
  p_values jsonb,
  auth_user_id text default null,
  p_record_id text default null
) returns text[]
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rtype text := coalesce(resolver->>'type', 'currentUser');
  field_id text;
  role_id text;
  relation_field_id text;
  nested_field_id text;
  raw text;
  ids text[];
  creator text;
  user_record_id text;
  auth_uuid uuid;
  branch jsonb;
  nested_resolver jsonb;
  hop_path text[];
  via_elem text;
  fan_out boolean;
  cursors jsonb[] := array[]::jsonb[];
  next_cursors jsonb[] := array[]::jsonb[];
  cursor_values jsonb;
  hop_id text;
  hop_raw text;
  hop_ids text[];
  related_id text;
  related_values jsonb;
  related_entity_id text;
  collected text[] := array[]::text[];
  user_id text;
  hop_index int;
  hop_depth int;
  depths jsonb;
  depth_elem jsonb;
  linked_child jsonb;
  child_entity_id text;
  child_parent_field_id text;
  parent_record_id text;
  child_label text;
  trigger_entity_id text;
  trigger_label text;
  cursor_ids text[] := array[]::text[];
  next_cursor_ids text[] := array[]::text[];
  cursor_id text;
  cursor_entity_id text;
  gip_ids text[];
  manager_field_id text;
  idx int;
begin
  case rtype
    when 'none' then
      return array[]::text[];

    when 'conditional' then
      for branch in
        select value
        from jsonb_array_elements(coalesce(resolver->'branches', '[]'::jsonb)) as t(value)
      loop
        if public.automation_conditions_match(
          coalesce(
            branch->'conditions',
            '{"version":1,"match":"all","rules":[]}'::jsonb
          ),
          coalesce(p_values, '{}'::jsonb),
          coalesce(p_values, '{}'::jsonb)
        ) then
          nested_resolver := coalesce(branch->'resolver', '{"type":"currentUser"}'::jsonb);
          if coalesce(nested_resolver->>'type', '') = 'conditional' then
            nested_resolver := '{"type":"currentUser"}'::jsonb;
          end if;
          return public.automation_resolve_assignees(
            nested_resolver,
            p_values,
            auth_user_id,
            p_record_id
          );
        end if;
      end loop;

      nested_resolver := coalesce(
        resolver->'elseResolver',
        resolver->'else_resolver',
        '{"type":"currentUser"}'::jsonb
      );
      if coalesce(nested_resolver->>'type', '') = 'conditional' then
        nested_resolver := '{"type":"currentUser"}'::jsonb;
      end if;
      return public.automation_resolve_assignees(
        nested_resolver,
        p_values,
        auth_user_id,
        p_record_id
      );

    when 'fixedUsers' then
      return coalesce(
        (select array_agg(x) from jsonb_array_elements_text(
          coalesce(resolver->'userIds', resolver->'user_ids', '[]'::jsonb)
        ) as t(x)),
        array[]::text[]
      );

    when 'field' then
      field_id := coalesce(
        nullif(trim(coalesce(resolver->>'fieldId', '')), ''),
        nullif(trim(coalesce(resolver->>'field_id', '')), '')
      );
      if field_id is null then
        return array[]::text[];
      end if;
      raw := coalesce(p_values->>field_id, '');
      ids := public.automation_field_ids(raw);
      if cardinality(ids) > 0 then
        return array[ids[1]];
      end if;
      return array[]::text[];

    when 'relationFieldFanOut' then
      field_id := coalesce(
        nullif(trim(coalesce(resolver->>'fieldId', '')), ''),
        nullif(trim(coalesce(resolver->>'field_id', '')), '')
      );
      if field_id is null then
        return array[]::text[];
      end if;
      raw := coalesce(p_values->>field_id, '');
      return public.automation_field_ids(raw);

    when 'relatedField' then
      relation_field_id := coalesce(
        nullif(trim(coalesce(resolver->>'relationFieldId', '')), ''),
        nullif(trim(coalesce(resolver->>'relation_field_id', '')), '')
      );
      nested_field_id := coalesce(
        nullif(trim(coalesce(resolver->>'fieldId', '')), ''),
        nullif(trim(coalesce(resolver->>'field_id', '')), '')
      );
      linked_child := coalesce(resolver->'linkedChild', resolver->'linked_child');
      if nested_field_id is null then
        return array[]::text[];
      end if;
      if relation_field_id is null and linked_child is null then
        return array[]::text[];
      end if;

      hop_path := array[]::text[];
      if relation_field_id is not null then
        hop_path := array[relation_field_id];
      end if;
      if jsonb_typeof(resolver->'via') = 'array' then
        for via_elem in
          select nullif(trim(x), '')
          from jsonb_array_elements_text(resolver->'via') as t(x)
        loop
          if via_elem is not null then
            hop_path := hop_path || via_elem;
          end if;
        end loop;
      elsif jsonb_typeof(resolver->'relationPath') = 'array' then
        hop_path := array[]::text[];
        for via_elem in
          select nullif(trim(x), '')
          from jsonb_array_elements_text(resolver->'relationPath') as t(x)
        loop
          if via_elem is not null then
            hop_path := hop_path || via_elem;
          end if;
        end loop;
      elsif jsonb_typeof(resolver->'relation_path') = 'array' then
        hop_path := array[]::text[];
        for via_elem in
          select nullif(trim(x), '')
          from jsonb_array_elements_text(resolver->'relation_path') as t(x)
        loop
          if via_elem is not null then
            hop_path := hop_path || via_elem;
          end if;
        end loop;
      end if;

      if cardinality(hop_path) = 0 and linked_child is null then
        return array[]::text[];
      end if;

      depths := coalesce(
        resolver->'relationGroupsDepths',
        resolver->'relation_groups_depths',
        '[]'::jsonb
      );

      fan_out := coalesce(resolver->>'fanOut', resolver->>'fan_out') in ('true', 't', '1');

      select er.entity_id into trigger_entity_id
      from public.entity_records er
      where er.id = nullif(trim(coalesce(p_record_id, '')), '')
      limit 1;
      if trigger_entity_id is not null then
        select lower(replace(
          coalesce(e.definition->>'name', '') || ' ' || coalesce(e.definition->>'namePlural', ''),
          'ё', 'е'
        )) into trigger_label
        from public.entities e
        where e.id = trigger_entity_id
        limit 1;
      end if;

      cursors := array[coalesce(p_values, '{}'::jsonb)];
      cursor_ids := array[nullif(trim(coalesce(p_record_id, '')), '')];

      if linked_child is not null and jsonb_typeof(linked_child) = 'object' then
        child_entity_id := nullif(trim(coalesce(
          linked_child->>'entityId',
          linked_child->>'entity_id',
          ''
        )), '');
        child_parent_field_id := nullif(trim(coalesce(
          linked_child->>'parentFieldId',
          linked_child->>'parent_field_id',
          ''
        )), '');
        parent_record_id := nullif(trim(coalesce(p_record_id, '')), '');
        if child_entity_id is null
           or child_parent_field_id is null
           or parent_record_id is null
        then
          return array[]::text[];
        end if;

        select lower(replace(
          coalesce(e.definition->>'name', '') || ' ' || coalesce(e.definition->>'namePlural', ''),
          'ё', 'е'
        )) into child_label
        from public.entities e
        where e.id = child_entity_id
        limit 1;
        if child_label is not null
           and position('отдел' in child_label) > 0
           and position('расчет' in child_label) > 0
        then
          fan_out := true;
        end if;

        next_cursors := array[]::jsonb[];
        next_cursor_ids := array[]::text[];
        for related_id in
          select er.id
          from public.entity_records er
          where er.entity_id = child_entity_id
            and parent_record_id = any (
              public.automation_field_ids(
                coalesce(er.field_values->>child_parent_field_id, '')
              )
            )
        loop
          select er.field_values
            into related_values
          from public.entity_records er
          where er.id = related_id
          limit 1;
          if related_values is not null then
            next_cursors := next_cursors || related_values;
            next_cursor_ids := next_cursor_ids || related_id;
            if not fan_out then
              exit;
            end if;
          end if;
        end loop;
        cursors := next_cursors;
        cursor_ids := next_cursor_ids;
        if cardinality(cursors) = 0 then
          return array[]::text[];
        end if;
      end if;

      if coalesce(trigger_label, '') like '%разбор%'
         and coalesce(trigger_label, '') like '%ткп%'
         and cardinality(hop_path) > 0
      then
        fan_out := true;
      end if;

      hop_index := 0;
      foreach hop_id in array hop_path
      loop
        hop_index := hop_index + 1;
        hop_depth := null;
        if jsonb_typeof(depths) = 'array' and jsonb_array_length(depths) >= hop_index then
          depth_elem := depths->(hop_index - 1);
          if jsonb_typeof(depth_elem) = 'number' then
            hop_depth := (depth_elem #>> '{}')::int;
          end if;
        end if;

        next_cursors := array[]::jsonb[];
        next_cursor_ids := array[]::text[];
        foreach cursor_values in array cursors
        loop
          hop_raw := coalesce(cursor_values->>hop_id, '');
          hop_ids := public.automation_bridge_record_ids(hop_raw, hop_depth);
          if not fan_out and cardinality(hop_ids) > 1 then
            hop_ids := array[hop_ids[1]];
          end if;
          if cardinality(hop_ids) = 0 then
            continue;
          end if;
          foreach related_id in array hop_ids
          loop
            select er.field_values
              into related_values
            from public.entity_records er
            where er.id = related_id
            limit 1;
            if related_values is not null then
              next_cursors := next_cursors || related_values;
              next_cursor_ids := next_cursor_ids || related_id;
            end if;
          end loop;
        end loop;
        cursors := next_cursors;
        cursor_ids := next_cursor_ids;
        if cardinality(cursors) = 0 then
          return array[]::text[];
        end if;
      end loop;

      collected := array[]::text[];
      idx := 0;
      foreach cursor_values in array cursors
      loop
        idx := idx + 1;
        cursor_id := null;
        if cardinality(cursor_ids) >= idx then
          cursor_id := cursor_ids[idx];
        end if;

        ids := public.automation_field_ids(coalesce(cursor_values->>nested_field_id, ''));

        -- Catalog «Руководитель(и)» by name when configured fieldId is absent/empty.
        if cardinality(ids) = 0 and cursor_id is not null then
          select er.entity_id into cursor_entity_id
          from public.entity_records er
          where er.id = cursor_id
          limit 1;
          if cursor_entity_id is not null then
            select nullif(trim(f->>'id'), '')
              into manager_field_id
            from public.entities e,
                 lateral jsonb_array_elements(coalesce(e.definition->'fields', '[]'::jsonb)) as f
            where e.id = cursor_entity_id
              and coalesce(f->>'type', '') in ('relation', 'belonging')
              and (
                lower(replace(coalesce(f->>'name', ''), 'ё', 'е')) = 'руководитель'
                or lower(replace(coalesce(f->>'name', ''), 'ё', 'е')) = 'руководители'
                or lower(replace(coalesce(f->>'name', ''), 'ё', 'е')) like 'руководитель %'
              )
            order by case
              when lower(replace(coalesce(f->>'name', ''), 'ё', 'е')) = 'руководитель' then 0
              when lower(replace(coalesce(f->>'name', ''), 'ё', 'е')) = 'руководители' then 1
              else 2
            end
            limit 1;
            if manager_field_id is not null and manager_field_id <> nested_field_id then
              ids := public.automation_field_ids(
                coalesce(cursor_values->>manager_field_id, '')
              );
            end if;
          end if;
        end if;

        -- Users leaf (managers stored as nested ids): the record is the assignee.
        if cardinality(ids) = 0 and cursor_id is not null then
          select er.entity_id into related_entity_id
          from public.entity_records er
          where er.id = cursor_id
          limit 1;
          if related_entity_id = 'entity-system-users' then
            ids := array[cursor_id];
          end if;
        end if;

        if cursor_id is not null
           and public.automation_record_looks_like_gip(cursor_id, cursor_values)
        then
          gip_ids := public.automation_trigger_gip_user_ids(
            nullif(trim(coalesce(p_record_id, '')), ''),
            coalesce(p_values, '{}'::jsonb)
          );
          if cardinality(gip_ids) > 0 then
            ids := gip_ids;
          end if;
        end if;

        if not fan_out and cardinality(ids) > 1 then
          ids := array[ids[1]];
        end if;
        foreach user_id in array ids
        loop
          if user_id is not null
             and btrim(user_id) <> ''
             and not (user_id = any (collected))
          then
            collected := collected || user_id;
          end if;
        end loop;
      end loop;

      return collected;

    when 'role' then
      role_id := coalesce(
        nullif(trim(coalesce(resolver->>'roleId', '')), ''),
        nullif(trim(coalesce(resolver->>'role_id', '')), '')
      );
      if role_id is null then
        return array[]::text[];
      end if;
      select coalesce(array_agg(er.id order by er.id), array[]::text[])
      into ids
      from public.entity_records er
      where er.entity_id = 'entity-system-users'
        and coalesce(er.field_values->>'field-system-users-role', '') = role_id;
      return ids;

    when 'recordCreator' then
      creator := coalesce(p_values->>'__createdByUserId', p_values->>'createdBy', '');
      if creator <> '' then
        return array[creator];
      end if;
    else
      null;
  end case;

  begin
    if auth_user_id is not null and length(trim(auth_user_id)) > 0 then
      begin
        auth_uuid := auth_user_id::uuid;
      exception when others then
        auth_uuid := null;
      end;
      if auth_uuid is not null then
        select er.id into user_record_id
        from public.entity_records er
        where er.entity_id = 'entity-system-users'
          and er.auth_user_id = auth_uuid
        limit 1;
        if user_record_id is not null then
          return array[user_record_id];
        end if;
        return array[trim(auth_user_id)];
      end if;
      return array[trim(auth_user_id)];
    end if;

    if auth.uid() is not null then
      select er.id into user_record_id
      from public.entity_records er
      where er.entity_id = 'entity-system-users'
        and er.auth_user_id = auth.uid()
      limit 1;
      if user_record_id is not null then
        return array[user_record_id];
      end if;
      return array[auth.uid()::text];
    end if;
  exception when others then
    null;
  end;

  return array[]::text[];
end;
$$;

grant execute on function public.automation_resolve_assignees(jsonb, jsonb, text, text)
  to authenticated, service_role;

-- Fan-out relatedField: do not create a single unassigned task when resolve
-- returns empty — that hides the data problem and blocks correct re-spawn.
create or replace function public.automation_spawn_template_for_record(
  p_tmpl public.automation_task_templates,
  p_process_id text,
  p_entity_id text,
  p_record_id text,
  p_trigger_field_id text,
  p_stored_option_id text,
  p_values jsonb,
  p_old_values jsonb,
  p_actor text
) returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  assignee_ids text[];
  assignee_id text;
  rtype text;
  task_id text;
  task_name text;
  task_description text;
  due timestamptz;
  template_snapshot jsonb;
  launch_phase text;
  autofill_outcome_id text;
  outcome_elem jsonb;
  first_task_id text := null;
  is_silent boolean;
  already boolean;
begin
  if coalesce(p_tmpl.enabled, true) = false then
    return null;
  end if;

  launch_phase := coalesce(nullif(p_tmpl.launch_phase, ''), 'onEnter');
  is_silent := p_tmpl.kind in ('autofill', 'actions');

  if is_silent then
    assignee_ids := array[null::text];
  else
    assignee_ids := public.automation_resolve_assignees(
      p_tmpl.assignee,
      p_values,
      p_actor,
      p_record_id
    );
    if cardinality(assignee_ids) = 0 then
      rtype := coalesce(p_tmpl.assignee->>'type', 'currentUser');
      if rtype in ('currentUser', 'recordCreator') then
        assignee_ids := public.automation_resolve_assignees(
          '{"type":"currentUser"}'::jsonb,
          p_values,
          p_actor,
          p_record_id
        );
      end if;
    end if;
    if cardinality(assignee_ids) = 0 then
      rtype := coalesce(p_tmpl.assignee->>'type', 'currentUser');
      -- relatedField / fan-out: skip null placeholder — fix data / resolve instead.
      if rtype in ('relatedField', 'relationFieldFanOut') then
        return null;
      end if;
      assignee_ids := array[null::text];
    end if;
  end if;

  template_snapshot := jsonb_build_object(
    'id', p_tmpl.id,
    'scenarioId', p_tmpl.scenario_id,
    'name', p_tmpl.name,
    'nameTemplate', p_tmpl.name_template,
    'description', p_tmpl.description,
    'triggerOptionId', p_tmpl.trigger_option_id,
    'stepOrder', p_tmpl.step_order,
    'isBlocking', p_tmpl.is_blocking,
    'enabled', coalesce(p_tmpl.enabled, true),
    'kind', p_tmpl.kind,
    'launchPhase', launch_phase,
    'launchConditions', p_tmpl.launch_conditions,
    'assignee', p_tmpl.assignee,
    'watchers', p_tmpl.watchers,
    'outcomes', p_tmpl.outcomes,
    'sla', p_tmpl.sla,
    'materials', p_tmpl.materials,
    'fieldAccess', coalesce(p_tmpl.field_access, '{}'::jsonb),
    'actions', coalesce(p_tmpl.actions, '[]'::jsonb),
    'viewFieldsPlacement', coalesce(
      nullif(p_tmpl.view_fields_placement, ''),
      'afterSelect'
    )
  );

  task_name := public.automation_render_template(
    case
      when nullif(btrim(p_tmpl.name_template), '') is not null then p_tmpl.name_template
      else p_tmpl.name
    end,
    p_values
  );
  if nullif(btrim(task_name), '') is null then
    task_name := p_tmpl.name;
  end if;

  task_description := public.automation_render_template(
    coalesce(p_tmpl.description, ''),
    p_values
  );

  due := null;
  if p_tmpl.sla is not null and (p_tmpl.sla->>'hours') is not null then
    begin
      due := now() + ((p_tmpl.sla->>'hours')::numeric || ' hours')::interval;
    exception when others then
      due := null;
    end;
  end if;

  autofill_outcome_id := null;
  if is_silent then
    for outcome_elem in
      select value
      from jsonb_array_elements(coalesce(p_tmpl.outcomes, '[]'::jsonb)) as value
    loop
      if public.automation_conditions_match(
        coalesce(
          outcome_elem->'conditions',
          '{"version":1,"match":"all","rules":[]}'::jsonb
        ),
        p_values,
        p_old_values
      ) then
        autofill_outcome_id := outcome_elem->>'id';
        exit;
      end if;
    end loop;
    if autofill_outcome_id is null then
      autofill_outcome_id := coalesce(p_tmpl.outcomes->0->>'id', '');
    end if;
  end if;

  foreach assignee_id in array assignee_ids
  loop
    select exists (
      select 1
      from public.automation_tasks existing
      where existing.record_id = p_record_id
        and existing.template_id = p_tmpl.id
        and coalesce(existing.assignee_user_id, '') = coalesce(assignee_id, '')
        and existing.status in ('pending', 'returned', 'completed')
    ) into already;
    if already then
      continue;
    end if;

    task_id := 'atask-' || gen_random_uuid()::text;
    begin
      insert into public.automation_tasks (
        id, process_id, scenario_id, template_id,
        entity_id, record_id, trigger_field_id, trigger_option_id,
        assignee_user_id, status, is_blocking, step_order,
        name, description, config, due_at, outcome_id
      ) values (
        task_id,
        p_process_id,
        p_tmpl.scenario_id,
        p_tmpl.id,
        p_entity_id,
        p_record_id,
        p_trigger_field_id,
        p_stored_option_id,
        assignee_id,
        'pending',
        p_tmpl.is_blocking,
        p_tmpl.step_order,
        task_name,
        task_description,
        template_snapshot,
        due,
        autofill_outcome_id
      );
      if first_task_id is null then
        first_task_id := task_id;
      end if;
    exception
      when unique_violation then
        continue;
      when others then
        raise warning 'automation spawn insert failed: %', sqlerrm;
        continue;
    end;

    if is_silent then
      continue;
    end if;

    begin
      perform public.automation_notify_from_rules(
        p_tmpl.id,
        'assigned',
        p_values,
        p_old_values,
        p_actor,
        'Назначена задача',
        'Назначена задача: ' || task_name,
        p_entity_id,
        p_record_id,
        task_id,
        assignee_id
      );
    exception when others then
      raise warning 'automation spawn notify failed: %', sqlerrm;
    end;
  end loop;

  return first_task_id;
end;
$$;

grant execute on function public.automation_spawn_template_for_record(
  public.automation_task_templates, text, text, text, text, text, jsonb, jsonb, text
) to authenticated, service_role;
-- <<< END 20261031160000_automation_resolve_user_leaf_fallback.sql

-- >>> BEGIN 20261031170000_automation_task_highlight_note.sql
-- Snapshot note shown on tasks spawned after a return-to-previous-stage
-- (e.g. reason text from a marked ask field).
alter table public.automation_tasks
  add column if not exists highlight_note jsonb;

comment on column public.automation_tasks.highlight_note is
  'Optional UI highlight for the task page, e.g. {kind:"return_reason",title,text,fieldLabel,sourceTaskId}';
-- <<< END 20261031170000_automation_task_highlight_note.sql

-- >>> BEGIN 20261031180000_automation_rework_stage_reentry.sql
-- Rework / return-to-stage: allow templates of the entered stage to spawn
-- again after a previous visit completed them.
--
-- Values stay on entity_records.field_values — the task form seeds defaults
-- from the record. We only supersede prior completed task rows so the
-- spawn dedupe (pending|returned|completed) no longer blocks re-entry.
--
-- Sequential spawn_next keeps the completed check unchanged (same visit).

create or replace function public.automation_supersede_stage_tasks(
  p_record_id text,
  p_process_id text,
  p_option_id text
) returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  option_id text;
  updated_count integer := 0;
begin
  option_id := nullif(btrim(coalesce(p_option_id, '')), '');
  if p_record_id is null or btrim(p_record_id) = '' then
    return 0;
  end if;
  if p_process_id is null or btrim(p_process_id) = '' then
    return 0;
  end if;
  if option_id is null then
    return 0;
  end if;

  update public.automation_tasks t
  set
    status = 'cancelled',
    updated_at = now()
  where t.record_id = p_record_id
    and t.process_id = p_process_id
    and t.status = 'completed'
    and (
      t.trigger_option_id = option_id
      or exists (
        select 1
        from public.automation_task_templates tmpl
        where tmpl.id = t.template_id
          and (
            tmpl.trigger_option_id = option_id
            or tmpl.trigger_option_id = any(public.automation_field_ids(option_id))
          )
      )
    );

  get diagnostics updated_count = row_count;
  return updated_count;
end;
$$;

grant execute on function public.automation_supersede_stage_tasks(text, text, text)
  to authenticated, service_role;

create or replace function public.automation_spawn_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := '{}'::jsonb;
  new_values jsonb := '{}'::jsonb;
  proc public.automation_processes%rowtype;
  scenario public.automation_scenarios%rowtype;
  tmpl public.automation_task_templates%rowtype;
  old_opt text;
  new_opt text;
  old_opt_id text;
  new_opt_id text;
  entered boolean;
  depth text;
  actor text;
  stored_option_id text;
  v_launch_phase text;
  store_on_prev boolean;
  is_prep_from_prev boolean;
  release_mode text;
  has_earlier boolean;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  if TG_OP <> 'INSERT' then
    old_values := coalesce(OLD.field_values, '{}'::jsonb);
  end if;
  if TG_OP <> 'DELETE' then
    new_values := coalesce(NEW.field_values, '{}'::jsonb);
  end if;

  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = NEW.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    old_opt := coalesce(old_values->>proc.trigger_field_id, '');
    new_opt := coalesce(new_values->>proc.trigger_field_id, '');
    old_opt_id := coalesce((public.automation_field_ids(old_opt))[1], '');
    new_opt_id := coalesce((public.automation_field_ids(new_opt))[1], '');

    if TG_OP = 'UPDATE'
       and old_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_assert_no_blocking(
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        old_opt_id
      );
    end if;

    entered := false;
    if proc.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      entered := true;
    elsif proc.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      entered := old_values is distinct from new_values;
    elsif proc.trigger_kind in ('fieldEnter', 'fieldTransition') then
      entered := new_opt_id is distinct from old_opt_id and new_opt_id <> '';
    elsif proc.trigger_kind = 'fieldLeave' then
      entered := new_opt_id is distinct from old_opt_id and old_opt_id <> '';
    end if;

    if not entered then
      continue;
    end if;

    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, new_values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by (
          select count(*)::int
          from public.automation_task_templates t
          where t.scenario_id = s.id
            and coalesce(t.enabled, true) = true
        ) desc,
        s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    -- True stage re-entry: free prior completed tasks so templates can spawn
    -- again. Same-visit sequential still blocked by completed after this land.
    if new_opt_id <> '' and old_opt_id is distinct from new_opt_id then
      perform public.automation_supersede_stage_tasks(
        NEW.id,
        proc.id,
        new_opt_id
      );
    end if;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and coalesce(t.enabled, true) = true
        and public.automation_conditions_match(t.launch_conditions, new_values, old_values)
        and (
          (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'onEnter'
            and (
              t.trigger_option_id = ''
              or t.trigger_option_id = new_opt
              or t.trigger_option_id = new_opt_id
              or t.trigger_option_id = any(public.automation_field_ids(new_opt))
            )
          )
          or (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
            and (
              exists (
                select 1
                from jsonb_array_elements(
                  coalesce(scenario.stage_transitions, '[]'::jsonb)
                ) st
                where coalesce(st->>'fromOptionId', st->>'from_option_id', '')
                      in (new_opt_id, new_opt)
                  and coalesce(st->>'toOptionId', st->>'to_option_id', '')
                      = t.trigger_option_id
              )
              or (
                (
                  t.trigger_option_id = new_opt
                  or t.trigger_option_id = new_opt_id
                  or t.trigger_option_id = any(public.automation_field_ids(new_opt))
                )
                and not exists (
                  select 1
                  from public.automation_tasks existing
                  where existing.record_id = NEW.id
                    and existing.template_id = t.id
                    and existing.status in ('pending', 'returned', 'completed')
                )
              )
            )
          )
        )
      order by
        case
          when coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
            then 0
          else 1
        end,
        t.step_order asc,
        t.created_at asc,
        t.id asc
    loop
      v_launch_phase := coalesce(nullif(tmpl.launch_phase, ''), 'onEnter');

      is_prep_from_prev :=
        v_launch_phase = 'beforeEnter'
        and exists (
          select 1
          from jsonb_array_elements(
            coalesce(scenario.stage_transitions, '[]'::jsonb)
          ) st
          where coalesce(st->>'fromOptionId', st->>'from_option_id', '')
                in (new_opt_id, new_opt)
            and coalesce(st->>'toOptionId', st->>'to_option_id', '')
                = tmpl.trigger_option_id
        );

      store_on_prev := is_prep_from_prev;

      release_mode := coalesce(
        nullif(scenario.stage_task_release->>tmpl.trigger_option_id, ''),
        'parallel'
      );

      if release_mode = 'sequential' then
        select exists (
          select 1
          from public.automation_task_templates earlier
          where earlier.scenario_id = scenario.id
            and coalesce(earlier.enabled, true) = true
            and earlier.trigger_option_id = tmpl.trigger_option_id
            and coalesce(nullif(earlier.launch_phase, ''), 'onEnter') = v_launch_phase
            and (
              earlier.step_order < tmpl.step_order
              or (
                earlier.step_order = tmpl.step_order
                and (
                  earlier.created_at < tmpl.created_at
                  or (
                    earlier.created_at = tmpl.created_at
                    and earlier.id < tmpl.id
                  )
                )
              )
            )
            and public.automation_conditions_match(
              earlier.launch_conditions,
              new_values,
              old_values
            )
        ) into has_earlier;
        if has_earlier then
          continue;
        end if;

        if v_launch_phase = 'onEnter' then
          select exists (
            select 1
            from public.automation_task_templates be
            where be.scenario_id = scenario.id
              and coalesce(be.enabled, true) = true
              and be.trigger_option_id = tmpl.trigger_option_id
              and coalesce(nullif(be.launch_phase, ''), 'onEnter') = 'beforeEnter'
              and public.automation_conditions_match(
                be.launch_conditions,
                new_values,
                old_values
              )
              and (
                (
                  be.kind not in ('autofill', 'actions')
                  and not exists (
                    select 1
                    from public.automation_tasks done
                    where done.record_id = NEW.id
                      and done.template_id = be.id
                      and done.status = 'completed'
                  )
                )
                or (
                  be.kind in ('autofill', 'actions')
                  and not exists (
                    select 1
                    from public.automation_tasks spawned
                    where spawned.record_id = NEW.id
                      and spawned.template_id = be.id
                      and spawned.status in ('pending', 'returned', 'completed')
                  )
                )
              )
          ) into has_earlier;
          if has_earlier then
            continue;
          end if;
        end if;
      end if;

      if store_on_prev then
        stored_option_id := coalesce(nullif(new_opt_id, ''), new_opt);
      else
        stored_option_id := coalesce(
          nullif(tmpl.trigger_option_id, ''),
          nullif(new_opt_id, ''),
          new_opt
        );
      end if;

      perform public.automation_spawn_template_for_record(
        tmpl,
        proc.id,
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        stored_option_id,
        new_values,
        old_values,
        actor
      );
    end loop;
  end loop;

  return NEW;
end;
$$;

create or replace function public.automation_ensure_before_enter_prep(
  p_record_id text,
  p_to_option_id text
) returns setof public.automation_tasks
language plpgsql
security definer
set search_path = public
as $$
declare
  rec public.entity_records%rowtype;
  proc public.automation_processes%rowtype;
  scenario public.automation_scenarios%rowtype;
  tmpl public.automation_task_templates%rowtype;
  values jsonb;
  old_values jsonb := '{}'::jsonb;
  actor text;
  from_opt text;
  to_opt text;
  spawned_id text;
begin
  if p_record_id is null or btrim(p_record_id) = '' then
    return;
  end if;
  to_opt := nullif(btrim(coalesce(p_to_option_id, '')), '');
  if to_opt is null then
    return;
  end if;

  select * into rec from public.entity_records where id = p_record_id;
  if rec.id is null then
    return;
  end if;

  values := coalesce(rec.field_values, '{}'::jsonb);
  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = rec.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    from_opt := coalesce(
      (public.automation_field_ids(coalesce(values->>proc.trigger_field_id, '')))[1],
      ''
    );
    if from_opt = '' or from_opt = to_opt then
      continue;
    end if;

    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by (
          select count(*)::int
          from public.automation_task_templates t
          where t.scenario_id = s.id
            and coalesce(t.enabled, true) = true
        ) desc,
        s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    -- Re-visit only: prior completed onEnter for destination, or beforeEnter
    -- completed from a different stage than the current one (not the prep
    -- just finished on this from_opt while first attempting the move).
    if exists (
      select 1
      from public.automation_tasks t
      join public.automation_task_templates tmpl on tmpl.id = t.template_id
      where t.record_id = rec.id
        and t.process_id = proc.id
        and t.status = 'completed'
        and coalesce(nullif(tmpl.launch_phase, ''), 'onEnter') = 'onEnter'
        and (
          tmpl.trigger_option_id = to_opt
          or t.trigger_option_id = to_opt
        )
    )
    or (
      exists (
        select 1
        from public.automation_tasks t
        join public.automation_task_templates tmpl on tmpl.id = t.template_id
        where t.record_id = rec.id
          and t.process_id = proc.id
          and t.status = 'completed'
          and coalesce(nullif(tmpl.launch_phase, ''), 'onEnter') = 'beforeEnter'
          and tmpl.trigger_option_id = to_opt
      )
      and not exists (
        select 1
        from public.automation_tasks t
        join public.automation_task_templates tmpl on tmpl.id = t.template_id
        where t.record_id = rec.id
          and t.process_id = proc.id
          and t.status in ('pending', 'returned', 'completed')
          and coalesce(nullif(tmpl.launch_phase, ''), 'onEnter') = 'beforeEnter'
          and tmpl.trigger_option_id = to_opt
          and t.trigger_option_id = from_opt
      )
    ) then
      perform public.automation_supersede_stage_tasks(rec.id, proc.id, to_opt);
    end if;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and coalesce(t.enabled, true) = true
        and coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
        and t.trigger_option_id = to_opt
        and public.automation_conditions_match(t.launch_conditions, values, old_values)
      order by t.step_order asc, t.created_at asc
    loop
      if exists (
        select 1
        from public.automation_tasks existing
        where existing.record_id = rec.id
          and existing.template_id = tmpl.id
          and existing.status in ('pending', 'returned', 'completed')
      ) then
        continue;
      end if;

      spawned_id := public.automation_spawn_template_for_record(
        tmpl,
        proc.id,
        rec.entity_id,
        rec.id,
        proc.trigger_field_id,
        from_opt,
        values,
        old_values,
        actor
      );
    end loop;
  end loop;

  return query
  select t.*
  from public.automation_tasks t
  where t.record_id = p_record_id
    and t.status in ('pending', 'returned')
    and (
      coalesce(t.config->>'launchPhase', t.config->>'launch_phase', '') = 'beforeEnter'
      or t.trigger_option_id = to_opt
    );
end;
$$;

grant execute on function public.automation_ensure_before_enter_prep(text, text)
  to authenticated, service_role;

-- cancelTasks may also clear completed rows so builders can free
-- templates before a stage return (complements supersede-on-enter).

create or replace function public.complete_automation_task(
  p_task_id text,
  p_outcome_id text,
  p_actor_user_id text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  task public.automation_tasks%rowtype;
  outcome jsonb;
  actions jsonb;
  action jsonb;
  field_id text;
  field_value text;
  rec public.entity_records%rowtype;
  lower_pending integer;
  lower_names text;
  run_id text;
  actions_log jsonb := '[]'::jsonb;
  next_task_id text;
  values_changed boolean := false;
  launch_phase text;
  dest_option text;
  trigger_field text;
  stage_already_set boolean := false;
  task_phase text;
  task_stage text;
  wait_for_siblings boolean := false;
  complete_when text;
begin
  select * into task from public.automation_tasks where id = p_task_id for update;
  if task.id is null then
    raise exception 'Task not found';
  end if;
  if task.status <> 'pending' and task.status <> 'returned' then
    raise exception 'Task is not pending';
  end if;

  task_phase := coalesce(
    nullif(btrim(coalesce(task.config->>'launchPhase', '')), ''),
    nullif(btrim(coalesce(task.config->>'launch_phase', '')), ''),
    'onEnter'
  );
  task_stage := coalesce(
    nullif(btrim(coalesce(task.config->>'triggerOptionId', '')), ''),
    nullif(btrim(coalesce(task.config->>'trigger_option_id', '')), ''),
    nullif(btrim(coalesce(task.trigger_option_id, '')), ''),
    ''
  );

  select
    count(*)::integer,
    string_agg(
      coalesce(nullif(btrim(t.name), ''), 'Задача'),
      ', '
      order by
        case
          when coalesce(
            nullif(btrim(coalesce(t.config->>'launchPhase', '')), ''),
            nullif(btrim(coalesce(t.config->>'launch_phase', '')), ''),
            'onEnter'
          ) = 'beforeEnter' then 0
          else 1
        end,
        t.step_order,
        t.created_at
    )
  into lower_pending, lower_names
  from public.automation_tasks t
  where t.record_id = task.record_id
    and t.status = 'pending'
    and t.is_blocking = true
    and t.id <> task.id
    and coalesce(t.config->>'kind', '') not in ('autofill', 'actions')
    and coalesce(
      nullif(btrim(coalesce(t.config->>'triggerOptionId', '')), ''),
      nullif(btrim(coalesce(t.config->>'trigger_option_id', '')), ''),
      nullif(btrim(coalesce(t.trigger_option_id, '')), ''),
      ''
    ) = task_stage
    and (
      (
        task_phase = 'onEnter'
        and coalesce(
          nullif(btrim(coalesce(t.config->>'launchPhase', '')), ''),
          nullif(btrim(coalesce(t.config->>'launch_phase', '')), ''),
          'onEnter'
        ) = 'beforeEnter'
      )
      or (
        coalesce(
          nullif(btrim(coalesce(t.config->>'launchPhase', '')), ''),
          nullif(btrim(coalesce(t.config->>'launch_phase', '')), ''),
          'onEnter'
        ) = task_phase
        and t.step_order < task.step_order
      )
    );

  if lower_pending > 0 then
    raise exception 'AUTOMATION_ORDER: Сначала выполните: %', lower_names
      using errcode = 'P0001';
  end if;

  select o into outcome
  from jsonb_array_elements(coalesce(task.config->'outcomes', '[]'::jsonb)) as o
  where o->>'id' = p_outcome_id
  limit 1;

  if outcome is null then
    select o into outcome
    from jsonb_array_elements(coalesce(task.config->'outcomes', '[]'::jsonb)) as o
    limit 1;
  end if;

  if outcome is null then
    raise exception 'Outcome not found';
  end if;

  select * into rec from public.entity_records where id = task.record_id for update;
  if rec.id is null then
    raise exception 'Record not found';
  end if;

  select nullif(btrim(coalesce(p.trigger_field_id, '')), '')
  into trigger_field
  from public.automation_processes p
  where p.id = task.process_id;

  -- Other assignees still open → defer stage moves only for completeWhen=all.
  complete_when := lower(coalesce(
    nullif(btrim(coalesce(task.config->'assignee'->>'completeWhen', '')), ''),
    nullif(btrim(coalesce(task.config->'assignee'->>'complete_when', '')), ''),
    'all'
  ));
  if nullif(trim(coalesce(task.template_id, '')), '') is not null
     and complete_when <> 'any'
  then
    select exists (
      select 1
      from public.automation_tasks sibling
      where sibling.record_id = task.record_id
        and sibling.template_id = task.template_id
        and sibling.process_id is not distinct from task.process_id
        and sibling.id <> task.id
        and sibling.status in ('pending', 'returned')
    ) into wait_for_siblings;
  end if;

  actions := coalesce(outcome->'actions', '[]'::jsonb);
  for action in select * from jsonb_array_elements(actions)
  loop
    if action->>'kind' = 'setField' then
      field_id := coalesce(
        nullif(trim(coalesce(action->>'fieldId', '')), ''),
        nullif(trim(coalesce(action->>'field_id', '')), '')
      );
      field_value := public.automation_resolve_action_value(
        coalesce(action->>'value', ''),
        coalesce(rec.field_values, '{}'::jsonb),
        p_actor_user_id
      );
      if field_id is not null then
        if wait_for_siblings
           and trigger_field is not null
           and field_id = trigger_field
        then
          actions_log := actions_log || jsonb_build_array(
            jsonb_build_object(
              'kind', 'setField',
              'fieldId', field_id,
              'deferredUntilAllAssignees', true
            )
          );
        else
          rec.field_values := jsonb_set(
            coalesce(rec.field_values, '{}'::jsonb),
            array[field_id],
            to_jsonb(field_value),
            true
          );
          values_changed := true;
          actions_log := actions_log || jsonb_build_array(
            jsonb_build_object('kind', 'setField', 'fieldId', field_id)
          );
        end if;
      end if;
    elsif action->>'kind' = 'setFieldPrevious' then
      field_id := coalesce(
        nullif(trim(coalesce(action->>'fieldId', '')), ''),
        nullif(trim(coalesce(action->>'field_id', '')), '')
      );
      if field_id is not null then
        actions_log := actions_log || jsonb_build_array(
          jsonb_build_object('kind', 'setFieldPrevious', 'fieldId', field_id, 'deferred', true)
        );
      end if;
    elsif action->>'kind' = 'noop' then
      actions_log := actions_log || jsonb_build_array(jsonb_build_object('kind', 'noop'));
    elsif action->>'kind' = 'cancelTasks' then
      update public.automation_tasks t
      set status = 'cancelled', updated_at = now()
      where t.record_id = task.record_id
        and t.status in ('pending', 'completed')
        and t.id <> task.id
        and (
          action->'templateIds' is null
          or jsonb_array_length(coalesce(action->'templateIds', '[]'::jsonb)) = 0
          or t.template_id in (
            select jsonb_array_elements_text(coalesce(action->'templateIds', '[]'::jsonb))
          )
        );
      actions_log := actions_log || jsonb_build_array(jsonb_build_object('kind', 'cancelTasks'));
    end if;
  end loop;

  launch_phase := task_phase;
  dest_option := task_stage;

  if launch_phase = 'beforeEnter'
     and dest_option <> ''
     and trigger_field is not null
     and not wait_for_siblings
  then
    select exists (
      select 1
      from jsonb_array_elements(actions) as a(value)
      where a.value->>'kind' = 'setField'
        and coalesce(
          nullif(trim(coalesce(a.value->>'fieldId', '')), ''),
          nullif(trim(coalesce(a.value->>'field_id', '')), '')
        ) = trigger_field
    ) into stage_already_set;

    if not stage_already_set then
      rec.field_values := jsonb_set(
        coalesce(rec.field_values, '{}'::jsonb),
        array[trigger_field],
        to_jsonb(dest_option),
        true
      );
      values_changed := true;
      actions_log := actions_log || jsonb_build_array(
        jsonb_build_object(
          'kind', 'setField',
          'fieldId', trigger_field,
          'autoBeforeEnter', true
        )
      );
    end if;
  elsif launch_phase = 'beforeEnter' and wait_for_siblings then
    actions_log := actions_log || jsonb_build_array(
      jsonb_build_object(
        'kind', 'setField',
        'fieldId', trigger_field,
        'autoBeforeEnter', true,
        'deferredUntilAllAssignees', true
      )
    );
  end if;

  update public.automation_tasks
  set
    status = 'completed',
    outcome_id = coalesce(outcome->>'id', p_outcome_id),
    completed_at = now(),
    updated_at = now()
  where id = task.id;

  begin
    perform public.automation_notify_from_rules(
      task.template_id,
      'completed',
      coalesce(rec.field_values, '{}'::jsonb),
      coalesce(rec.field_values, '{}'::jsonb),
      p_actor_user_id,
      'Завершена задача',
      'Завершена задача: ' || task.name,
      task.entity_id,
      task.record_id,
      task.id,
      task.assignee_user_id
    );
  exception when others then
    raise warning 'automation complete notify failed: %', sqlerrm;
  end;

  -- Allow spawn trigger; suppress blocking assert for this stage write.
  perform set_config('automation.execution_depth', '0', true);
  perform set_config('automation.inside_complete', '1', true);

  select * into task from public.automation_tasks where id = p_task_id;
  next_task_id := public.automation_spawn_next_sequential_task(task, p_actor_user_id);
  if next_task_id is not null then
    actions_log := actions_log || jsonb_build_array(
      jsonb_build_object('kind', 'spawnNextSequential', 'taskId', next_task_id)
    );
  end if;

  if values_changed then
    update public.entity_records
    set field_values = rec.field_values, updated_at = now()
    where id = rec.id;
  end if;

  perform set_config('automation.inside_complete', '0', true);

  run_id := 'arun-' || gen_random_uuid()::text;
  insert into public.automation_runs (id, cause, entity_id, record_id, task_id, actions_log, status)
  values (run_id, 'complete', task.entity_id, task.record_id, task.id, actions_log, 'ok');

  return jsonb_build_object(
    'taskId', task.id,
    'runId', run_id,
    'outcomeId', coalesce(outcome->>'id', p_outcome_id),
    'actionsLog', actions_log,
    'nextTaskId', next_task_id,
    'waitingForAssignees', wait_for_siblings,
    'fieldValues', coalesce(rec.field_values, '{}'::jsonb)
  );
exception
  when others then
    perform set_config('automation.execution_depth', '0', true);
    perform set_config('automation.inside_complete', '0', true);
    raise;
end;
$$;

grant execute on function public.complete_automation_task(text, text, text)
  to authenticated, service_role;
-- <<< END 20261031180000_automation_rework_stage_reentry.sql

