CREATE OR REPLACE FUNCTION public.reschedule_project_gantt_work_item(
  p_project_entity_id text,
  p_project_record_id text,
  p_work_item_id uuid,
  p_new_start_date date,
  p_new_end_date date,
  p_idempotency_key uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  existing public.project_gantt_reschedule_executions%ROWTYPE;
  root public.project_work_items%ROWTYPE;
  item public.project_work_items%ROWTYPE;
  edge record;
  reachable uuid[] := ARRAY[p_work_item_id];
  frontier uuid[] := ARRAY[p_work_item_id];
  current uuid;
  next_ids uuid[];
  order_ids uuid[] := ARRAY[]::uuid[];
  indegree jsonb := '{}'::jsonb;
  ready uuid[] := ARRAY[]::uuid[];
  pred_count integer;
  duration integer;
  bound date;
  lower_bound date;
  new_start date;
  new_end date;
  dates jsonb := '{}'::jsonb;
  changes jsonb := '[]'::jsonb;
  change_count integer := 0;
  execution_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Необходима авторизация';
  END IF;

  SELECT * INTO existing
  FROM public.project_gantt_reschedule_executions
  WHERE project_entity_id = p_project_entity_id
    AND project_record_id = p_project_record_id
    AND idempotency_key = p_idempotency_key;
  IF existing.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'executionId', existing.id,
      'replayed', true,
      'changedCount', existing.changed_count,
      'changes', existing.result_payload->'changes'
    );
  END IF;

  SELECT * INTO root
  FROM public.project_work_items
  WHERE id = p_work_item_id
    AND project_entity_id = p_project_entity_id
    AND project_record_id = p_project_record_id;
  IF root.id IS NULL THEN
    RAISE EXCEPTION 'Корневая работа не найдена';
  END IF;

  LOOP
    EXIT WHEN cardinality(frontier) = 0;
    current := frontier[1];
    frontier := frontier[2:];
    SELECT COALESCE(array_agg(d.successor_work_item_id ORDER BY d.successor_work_item_id), ARRAY[]::uuid[])
      INTO next_ids
    FROM public.project_work_item_dependencies d
    WHERE d.predecessor_work_item_id = current
      AND d.project_entity_id = p_project_entity_id
      AND d.project_record_id = p_project_record_id;
    FOR i IN 1..COALESCE(cardinality(next_ids), 0) LOOP
      IF NOT (next_ids[i] = ANY (reachable)) THEN
        reachable := reachable || next_ids[i];
        frontier := frontier || next_ids[i];
      END IF;
    END LOOP;
  END LOOP;

  FOREACH current IN ARRAY reachable LOOP
    SELECT COUNT(DISTINCT d.predecessor_work_item_id)::integer INTO pred_count
    FROM public.project_work_item_dependencies d
    WHERE d.successor_work_item_id = current
      AND d.project_entity_id = p_project_entity_id
      AND d.project_record_id = p_project_record_id
      AND d.predecessor_work_item_id = ANY (reachable);
    indegree := indegree || jsonb_build_object(current::text, pred_count);
    IF pred_count = 0 THEN
      ready := array_append(ready, current);
    END IF;
  END LOOP;
  ready := (SELECT COALESCE(array_agg(x ORDER BY x), ARRAY[]::uuid[]) FROM unnest(ready) x);

  WHILE cardinality(ready) > 0 LOOP
    current := ready[1];
    ready := ready[2:];
    order_ids := array_append(order_ids, current);
    SELECT COALESCE(array_agg(d.successor_work_item_id ORDER BY d.successor_work_item_id), ARRAY[]::uuid[])
      INTO next_ids
    FROM public.project_work_item_dependencies d
    WHERE d.predecessor_work_item_id = current
      AND d.project_entity_id = p_project_entity_id
      AND d.project_record_id = p_project_record_id
      AND d.successor_work_item_id = ANY (reachable);
    FOR i IN 1..COALESCE(cardinality(next_ids), 0) LOOP
      pred_count := (indegree->>next_ids[i]::text)::integer - 1;
      indegree := indegree || jsonb_build_object(next_ids[i]::text, pred_count);
      IF pred_count = 0 THEN
        ready := array_append(ready, next_ids[i]);
        ready := (SELECT COALESCE(array_agg(x ORDER BY x), ARRAY[]::uuid[]) FROM unnest(ready) x);
      END IF;
    END LOOP;
  END LOOP;

  IF cardinality(order_ids) <> cardinality(reachable) THEN
    RAISE EXCEPTION 'Граф зависимостей содержит цикл';
  END IF;

  FOR item IN
    SELECT * FROM public.project_work_items
    WHERE project_entity_id = p_project_entity_id
      AND project_record_id = p_project_record_id
  LOOP
    dates := dates || jsonb_build_object(
      item.id::text,
      jsonb_build_object('start', item.task_start_date, 'end', item.task_due_date)
    );
  END LOOP;

  dates := dates || jsonb_build_object(
    root.id::text,
    jsonb_build_object('start', p_new_start_date, 'end', p_new_end_date)
  );

  IF root.task_start_date IS DISTINCT FROM p_new_start_date
     OR root.task_due_date IS DISTINCT FROM p_new_end_date THEN
    UPDATE public.project_work_items
    SET task_start_date = p_new_start_date,
        task_due_date = p_new_end_date,
        updated_at = now()
    WHERE id = root.id;
    changes := changes || jsonb_build_array(jsonb_build_object(
      'workItemId', root.id,
      'oldStartDate', root.task_start_date,
      'oldEndDate', root.task_due_date,
      'newStartDate', p_new_start_date,
      'newEndDate', p_new_end_date
    ));
    change_count := change_count + 1;
  END IF;

  FOREACH current IN ARRAY order_ids LOOP
    CONTINUE WHEN current = root.id;
    SELECT * INTO item FROM public.project_work_items WHERE id = current;
    duration := public.project_gantt_business_duration(
      item.task_start_date, item.task_due_date
    );
    CONTINUE WHEN duration IS NULL;

    lower_bound := NULL;
    FOR edge IN
      SELECT *
      FROM public.project_work_item_dependencies d
      WHERE d.successor_work_item_id = current
        AND d.project_entity_id = p_project_entity_id
        AND d.project_record_id = p_project_record_id
      ORDER BY d.predecessor_work_item_id, d.dependency_type::text
    LOOP
      IF edge.dependency_type IN ('finish_to_start', 'finish_to_finish') THEN
        IF (dates->edge.predecessor_work_item_id::text->>'end') IS NULL THEN
          RAISE EXCEPTION 'У предшественника не задан срок окончания';
        END IF;
        bound := CASE
          WHEN edge.dependency_type = 'finish_to_start' THEN
            public.project_gantt_add_business_days(
              (dates->edge.predecessor_work_item_id::text->>'end')::date, 1
            )
          ELSE
            public.project_gantt_add_business_days(
              (dates->edge.predecessor_work_item_id::text->>'end')::date,
              -(duration - 1)
            )
        END;
      ELSE
        IF (dates->edge.predecessor_work_item_id::text->>'start') IS NULL THEN
          RAISE EXCEPTION 'У предшественника не задан срок начала';
        END IF;
        bound := CASE
          WHEN edge.dependency_type = 'start_to_start' THEN
            (dates->edge.predecessor_work_item_id::text->>'start')::date
          ELSE
            public.project_gantt_add_business_days(
              (dates->edge.predecessor_work_item_id::text->>'start')::date,
              -(duration - 1)
            )
        END;
      END IF;
      bound := public.project_gantt_add_business_days(bound, edge.lag_business_days);
      IF lower_bound IS NULL OR bound > lower_bound THEN
        lower_bound := bound;
      END IF;
    END LOOP;

    CONTINUE WHEN lower_bound IS NULL;
    new_start := lower_bound;
    new_end := public.project_gantt_add_business_days(new_start, duration - 1);
    dates := dates || jsonb_build_object(
      current::text,
      jsonb_build_object('start', new_start, 'end', new_end)
    );
    IF item.task_start_date IS DISTINCT FROM new_start
       OR item.task_due_date IS DISTINCT FROM new_end THEN
      UPDATE public.project_work_items
      SET task_start_date = new_start,
          task_due_date = new_end,
          updated_at = now()
      WHERE id = current;
      changes := changes || jsonb_build_array(jsonb_build_object(
        'workItemId', current,
        'oldStartDate', item.task_start_date,
        'oldEndDate', item.task_due_date,
        'newStartDate', new_start,
        'newEndDate', new_end
      ));
      change_count := change_count + 1;
    END IF;
  END LOOP;

  INSERT INTO public.project_gantt_reschedule_executions (
    project_entity_id,
    project_record_id,
    work_item_id,
    idempotency_key,
    new_start_date,
    new_end_date,
    changed_count,
    result_payload,
    created_by
  )
  VALUES (
    p_project_entity_id,
    p_project_record_id,
    p_work_item_id,
    p_idempotency_key,
    p_new_start_date,
    p_new_end_date,
    change_count,
    jsonb_build_object('changes', changes),
    auth.uid()
  )
  RETURNING id INTO execution_id;

  RETURN jsonb_build_object(
    'executionId', execution_id,
    'replayed', false,
    'changedCount', change_count,
    'changes', changes
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.reschedule_project_gantt_work_item(
  text, text, uuid, date, date, uuid
) TO authenticated;

CREATE OR REPLACE FUNCTION public.reorder_project_gantt_work_item(
  p_project_entity_id text,
  p_project_record_id text,
  p_work_item_id uuid,
  p_stage_id uuid,
  p_direction text,
  p_expected_order uuid[],
  p_idempotency_key uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  existing public.project_gantt_order_executions%ROWTYPE;
  current_order uuid[];
  idx integer;
  swap_idx integer;
  result_order uuid[];
  changed boolean := false;
  execution_id uuid;
  i integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Необходима авторизация';
  END IF;
  IF p_direction NOT IN ('up', 'down') THEN
    RAISE EXCEPTION 'Некорректное направление';
  END IF;

  SELECT * INTO existing
  FROM public.project_gantt_order_executions
  WHERE project_entity_id = p_project_entity_id
    AND project_record_id = p_project_record_id
    AND idempotency_key = p_idempotency_key;
  IF existing.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'executionId', existing.id,
      'replayed', true,
      'changed', existing.changed,
      'workItemOrder', to_jsonb(existing.result_order)
    );
  END IF;

  SELECT COALESCE(array_agg(id ORDER BY row_order, id), ARRAY[]::uuid[])
    INTO current_order
  FROM public.project_work_items
  WHERE project_entity_id = p_project_entity_id
    AND project_record_id = p_project_record_id
    AND stage_id IS NOT DISTINCT FROM p_stage_id;

  IF current_order IS DISTINCT FROM p_expected_order THEN
    RAISE EXCEPTION 'Ожидаемый порядок работ устарел';
  END IF;

  idx := array_position(current_order, p_work_item_id);
  IF idx IS NULL THEN
    RAISE EXCEPTION 'Перемещаемая задача отсутствует в ожидаемом порядке';
  END IF;

  swap_idx := CASE
    WHEN p_direction = 'up' THEN idx - 1
    ELSE idx + 1
  END;

  result_order := current_order;
  IF swap_idx BETWEEN 1 AND cardinality(current_order) THEN
    result_order[idx] := current_order[swap_idx];
    result_order[swap_idx] := current_order[idx];
    changed := true;
    FOR i IN 1..cardinality(result_order) LOOP
      UPDATE public.project_work_items
      SET row_order = i - 1, updated_at = now()
      WHERE id = result_order[i];
    END LOOP;
  END IF;

  INSERT INTO public.project_gantt_order_executions (
    project_entity_id,
    project_record_id,
    work_item_id,
    stage_id,
    direction,
    idempotency_key,
    expected_order,
    result_order,
    changed,
    created_by
  )
  VALUES (
    p_project_entity_id,
    p_project_record_id,
    p_work_item_id,
    p_stage_id,
    p_direction,
    p_idempotency_key,
    p_expected_order,
    result_order,
    changed,
    auth.uid()
  )
  RETURNING id INTO execution_id;

  RETURN jsonb_build_object(
    'executionId', execution_id,
    'replayed', false,
    'changed', changed,
    'workItemOrder', to_jsonb(result_order)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.reorder_project_gantt_work_item(
  text, text, uuid, uuid, text, uuid[], uuid
) TO authenticated;
-- <<< END 20261101130000_project_gantt_schedule_cmds.sql

-- >>> BEGIN 20261101140000_project_gantt_lifecycle.sql
-- Project Gantt lifecycle: revisions, decisions, publish, baseline, mutation guards.

CREATE TABLE IF NOT EXISTS public.project_gantt_revisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_entity_id text NOT NULL,
  project_record_id text NOT NULL,
  revision_number integer NOT NULL CHECK (revision_number > 0),
  cycle_number integer NOT NULL DEFAULT 1 CHECK (cycle_number > 0),
  status text NOT NULL
    CHECK (status IN (
      'draft',
      'leading_review',
      'department_review',
      'rework',
      'approved',
      'published',
      'superseded'
    )),
  resubmission_mode text NOT NULL DEFAULT 'initial'
    CHECK (resubmission_mode IN ('initial', 'targeted', 'all')),
  target_department_id text,
  target_department_name text,
  leading_department_id text,
  leading_department_name text,
  content_hash text NOT NULL DEFAULT '',
  snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid REFERENCES auth.users (id) ON DELETE SET NULL,
  created_by_name text,
  submitted_by uuid REFERENCES auth.users (id) ON DELETE SET NULL,
  submitted_by_name text,
  published_by uuid REFERENCES auth.users (id) ON DELETE SET NULL,
  published_by_name text,
  submitted_at timestamptz,
  returned_at timestamptz,
  approved_at timestamptz,
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT project_gantt_revisions_project_revision_uq
    UNIQUE (project_entity_id, project_record_id, revision_number)
);

CREATE INDEX IF NOT EXISTS idx_project_gantt_revisions_project_status
  ON public.project_gantt_revisions (project_entity_id, project_record_id, status);

CREATE TABLE IF NOT EXISTS public.project_gantt_revision_decisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  revision_id uuid NOT NULL REFERENCES public.project_gantt_revisions (id) ON DELETE CASCADE,
  project_entity_id text NOT NULL,
  project_record_id text NOT NULL,
  department_id text NOT NULL,
  department_name text NOT NULL DEFAULT '',
  role text NOT NULL CHECK (role IN ('leading', 'participant')),
  required boolean NOT NULL DEFAULT true,
  decision text NOT NULL DEFAULT 'pending'
    CHECK (decision IN ('pending', 'approved', 'rejected', 'superseded')),
  comment text,
  decided_by uuid REFERENCES auth.users (id) ON DELETE SET NULL,
  decided_by_name text,
  decided_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT project_gantt_revision_decisions_unique
    UNIQUE (revision_id, department_id)
);

CREATE TABLE IF NOT EXISTS public.project_gantt_lifecycle_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_entity_id text NOT NULL,
  project_record_id text NOT NULL,
  revision_id uuid REFERENCES public.project_gantt_revisions (id) ON DELETE SET NULL,
  action text NOT NULL,
  old_status text,
  new_status text,
  comment text,
  actor_id uuid REFERENCES auth.users (id) ON DELETE SET NULL,
  actor_name text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_project_gantt_lifecycle_history_project
  ON public.project_gantt_lifecycle_history (
    project_entity_id, project_record_id, created_at DESC
  );

ALTER TABLE public.project_gantt_project_state
  DROP CONSTRAINT IF EXISTS project_gantt_project_state_published_fk;
ALTER TABLE public.project_gantt_project_state
  ADD CONSTRAINT project_gantt_project_state_published_fk
  FOREIGN KEY (published_gantt_revision_id)
  REFERENCES public.project_gantt_revisions (id) ON DELETE SET NULL;

ALTER TABLE public.project_gantt_project_state
  DROP CONSTRAINT IF EXISTS project_gantt_project_state_baseline_fk;
ALTER TABLE public.project_gantt_project_state
  ADD CONSTRAINT project_gantt_project_state_baseline_fk
  FOREIGN KEY (baseline_gantt_revision_id)
  REFERENCES public.project_gantt_revisions (id) ON DELETE SET NULL;

ALTER TABLE public.project_gantt_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_gantt_revision_decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_gantt_lifecycle_history ENABLE ROW LEVEL SECURITY;

GRANT SELECT ON public.project_gantt_revisions TO authenticated;
GRANT SELECT ON public.project_gantt_revision_decisions TO authenticated;
GRANT SELECT ON public.project_gantt_lifecycle_history TO authenticated;
GRANT ALL ON public.project_gantt_revisions TO service_role;
GRANT ALL ON public.project_gantt_revision_decisions TO service_role;
GRANT ALL ON public.project_gantt_lifecycle_history TO service_role;
REVOKE INSERT, UPDATE, DELETE ON public.project_gantt_revisions FROM authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.project_gantt_revision_decisions FROM authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.project_gantt_lifecycle_history FROM authenticated;

DROP POLICY IF EXISTS project_gantt_revisions_select ON public.project_gantt_revisions;
CREATE POLICY project_gantt_revisions_select
  ON public.project_gantt_revisions FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS project_gantt_revision_decisions_select
  ON public.project_gantt_revision_decisions;
CREATE POLICY project_gantt_revision_decisions_select
  ON public.project_gantt_revision_decisions FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS project_gantt_lifecycle_history_select
  ON public.project_gantt_lifecycle_history;
CREATE POLICY project_gantt_lifecycle_history_select
  ON public.project_gantt_lifecycle_history FOR SELECT TO authenticated USING (true);

CREATE OR REPLACE FUNCTION public.project_gantt_assert_not_locked(
  p_project_entity_id text,
  p_project_record_id text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.project_gantt_revisions r
    WHERE r.project_entity_id = p_project_entity_id
      AND r.project_record_id = p_project_record_id
      AND r.status IN (
        'draft', 'leading_review', 'department_review', 'rework', 'approved'
      )
  ) THEN
    RAISE EXCEPTION 'PROJECT_GANTT_APPROVED_SNAPSHOT_LOCKED';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.upsert_project_gantt_work_item(
  p_project_entity_id text,
  p_project_record_id text,
  p_name text,
  p_stage_id uuid DEFAULT NULL,
  p_start_date date DEFAULT NULL,
  p_due_date date DEFAULT NULL,
  p_planned_hours numeric DEFAULT NULL,
  p_department_id text DEFAULT NULL,
  p_department_name text DEFAULT NULL,
  p_status text DEFAULT NULL,
  p_status_color text DEFAULT NULL,
  p_is_done boolean DEFAULT NULL,
  p_assignee_id text DEFAULT NULL,
  p_assignee_name text DEFAULT NULL,
  p_assignee_role text DEFAULT NULL,
  p_work_item_id uuid DEFAULT NULL
)
RETURNS public.project_work_items
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  row public.project_work_items%ROWTYPE;
  next_order integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Необходима авторизация';
  END IF;
  PERFORM public.ensure_project_gantt_project_state(
    p_project_entity_id, p_project_record_id, ''
  );
  PERFORM public.project_gantt_assert_not_locked(
    p_project_entity_id, p_project_record_id
  );

  IF p_work_item_id IS NOT NULL THEN
    UPDATE public.project_work_items
    SET name = COALESCE(NULLIF(btrim(p_name), ''), name),
        stage_id = COALESCE(p_stage_id, stage_id),
        task_start_date = p_start_date,
        task_due_date = p_due_date,
        planned_hours = COALESCE(p_planned_hours, planned_hours),
        department_id = COALESCE(p_department_id, department_id),
        department_name = COALESCE(p_department_name, department_name),
        status = COALESCE(NULLIF(btrim(p_status), ''), status),
        status_color = COALESCE(p_status_color, status_color),
        is_done = COALESCE(p_is_done, is_done),
        assignee_id = COALESCE(p_assignee_id, assignee_id),
        assignee_name = COALESCE(p_assignee_name, assignee_name),
        assignee_role = COALESCE(p_assignee_role, assignee_role),
        updated_at = now()
    WHERE id = p_work_item_id
      AND project_entity_id = p_project_entity_id
      AND project_record_id = p_project_record_id
    RETURNING * INTO row;
    IF row.id IS NULL THEN
      RAISE EXCEPTION 'Работа не найдена';
    END IF;
    RETURN row;
  END IF;

  SELECT COALESCE(MAX(row_order), -1) + 1 INTO next_order
  FROM public.project_work_items
  WHERE project_entity_id = p_project_entity_id
    AND project_record_id = p_project_record_id
    AND stage_id IS NOT DISTINCT FROM p_stage_id;

  INSERT INTO public.project_work_items (
    project_entity_id, project_record_id, stage_id, name,
    task_start_date, task_due_date, row_order, planned_hours,
    department_id, department_name, status, status_color, is_done,
    assignee_id, assignee_name, assignee_role, created_by
  )
  VALUES (
    p_project_entity_id, p_project_record_id, p_stage_id,
    NULLIF(btrim(p_name), ''), p_start_date, p_due_date, next_order,
    p_planned_hours, p_department_id, p_department_name,
    COALESCE(NULLIF(btrim(p_status), ''), 'В работе'), p_status_color,
    COALESCE(p_is_done, false), p_assignee_id, p_assignee_name,
    p_assignee_role, auth.uid()
  )
  RETURNING * INTO row;

  IF row.name IS NULL THEN
    RAISE EXCEPTION 'Название работы обязательно';
  END IF;
  RETURN row;
END;
$$;

CREATE OR REPLACE FUNCTION public.set_project_gantt_leading_department(
  p_project_entity_id text,
  p_project_record_id text,
  p_department_id text,
  p_department_name text,
  p_expected_department_id text DEFAULT NULL
)
RETURNS public.project_gantt_project_state
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  state public.project_gantt_project_state%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Необходима авторизация';
  END IF;
  state := public.ensure_project_gantt_project_state(
    p_project_entity_id, p_project_record_id, ''
  );

  IF EXISTS (
    SELECT 1 FROM public.project_gantt_revisions r
    WHERE r.project_entity_id = p_project_entity_id
      AND r.project_record_id = p_project_record_id
      AND r.status IN ('draft', 'leading_review', 'department_review', 'rework', 'approved')
  ) THEN
    RAISE EXCEPTION 'Ведущий отдел нельзя менять при открытой ревизии';
  END IF;

  IF p_expected_department_id IS DISTINCT FROM state.leading_department_id THEN
    RAISE EXCEPTION 'Ожидаемый ведущий отдел устарел';
  END IF;

  UPDATE public.project_gantt_project_state
  SET leading_department_id = NULLIF(btrim(p_department_id), ''),
      leading_department_name = COALESCE(NULLIF(btrim(p_department_name), ''), ''),
      updated_at = now()
  WHERE project_entity_id = p_project_entity_id
    AND project_record_id = p_project_record_id
  RETURNING * INTO state;

  INSERT INTO public.project_gantt_lifecycle_history (
    project_entity_id, project_record_id, action, comment, actor_id
  ) VALUES (
    p_project_entity_id, p_project_record_id, 'leading_department.change',
    state.leading_department_name, auth.uid()
  );

  RETURN state;
END;
$$;

GRANT EXECUTE ON FUNCTION public.set_project_gantt_leading_department(
  text, text, text, text, text
) TO authenticated;

CREATE OR REPLACE FUNCTION public.start_project_gantt_revision(
  p_project_entity_id text,
  p_project_record_id text,
  p_snapshot jsonb,
  p_content_hash text,
  p_idempotency_key uuid,
  p_created_by_name text DEFAULT NULL,
  p_resubmission_mode text DEFAULT 'initial',
  p_target_department_id text DEFAULT NULL,
  p_target_department_name text DEFAULT NULL
)
RETURNS public.project_gantt_revisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  state public.project_gantt_project_state%ROWTYPE;
  next_revision integer;
  next_cycle integer;
  row public.project_gantt_revisions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Необходима авторизация';
  END IF;
  state := public.ensure_project_gantt_project_state(
    p_project_entity_id, p_project_record_id, ''
  );
  IF state.leading_department_id IS NULL THEN
    RAISE EXCEPTION 'Сначала назначьте ведущий отдел';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.project_gantt_revisions r
    WHERE r.project_entity_id = p_project_entity_id
      AND r.project_record_id = p_project_record_id
      AND r.status IN ('draft', 'leading_review', 'department_review', 'rework', 'approved')
  ) THEN
    RAISE EXCEPTION 'Уже есть открытая ревизия графика';
  END IF;

  SELECT COALESCE(MAX(revision_number), 0) + 1,
         COALESCE(MAX(cycle_number), 0) + CASE
           WHEN p_resubmission_mode = 'initial' THEN 1 ELSE 0
         END
    INTO next_revision, next_cycle
  FROM public.project_gantt_revisions
  WHERE project_entity_id = p_project_entity_id
    AND project_record_id = p_project_record_id;

  IF next_cycle < 1 THEN next_cycle := 1; END IF;
  IF p_resubmission_mode <> 'initial' THEN
    SELECT COALESCE(MAX(cycle_number), 1) INTO next_cycle
    FROM public.project_gantt_revisions
    WHERE project_entity_id = p_project_entity_id
      AND project_record_id = p_project_record_id;
  END IF;

  INSERT INTO public.project_gantt_revisions (
    project_entity_id, project_record_id, revision_number, cycle_number,
    status, resubmission_mode, target_department_id, target_department_name,
    leading_department_id, leading_department_name, content_hash, snapshot,
    created_by, created_by_name
  )
  VALUES (
    p_project_entity_id, p_project_record_id, next_revision, next_cycle,
    'draft', COALESCE(p_resubmission_mode, 'initial'),
    p_target_department_id, p_target_department_name,
    state.leading_department_id, state.leading_department_name,
    COALESCE(p_content_hash, ''), COALESCE(p_snapshot, '{}'::jsonb),
    auth.uid(), p_created_by_name
  )
  RETURNING * INTO row;

  -- Leading department decision row.
  INSERT INTO public.project_gantt_revision_decisions (
    revision_id, project_entity_id, project_record_id,
    department_id, department_name, role, required
  ) VALUES (
    row.id, p_project_entity_id, p_project_record_id,
    state.leading_department_id, COALESCE(state.leading_department_name, ''),
    'leading', true
  );

  -- Participant departments from distinct work-item departments.
  INSERT INTO public.project_gantt_revision_decisions (
    revision_id, project_entity_id, project_record_id,
    department_id, department_name, role, required
  )
  SELECT DISTINCT ON (wi.department_id)
    row.id,
    p_project_entity_id,
    p_project_record_id,
    wi.department_id,
    COALESCE(wi.department_name, ''),
    'participant',
    true
  FROM public.project_work_items wi
  WHERE wi.project_entity_id = p_project_entity_id
    AND wi.project_record_id = p_project_record_id
    AND wi.department_id IS NOT NULL
    AND wi.department_id <> state.leading_department_id
  ORDER BY wi.department_id
  ON CONFLICT DO NOTHING;

  INSERT INTO public.project_gantt_lifecycle_history (
    project_entity_id, project_record_id, revision_id, action,
    new_status, actor_id, actor_name
  ) VALUES (
    p_project_entity_id, p_project_record_id, row.id, 'revision.start',
    'draft', auth.uid(), p_created_by_name
  );

  RETURN row;
END;
$$;

GRANT EXECUTE ON FUNCTION public.start_project_gantt_revision(
  text, text, jsonb, text, uuid, text, text, text, text
) TO authenticated;

CREATE OR REPLACE FUNCTION public.submit_project_gantt_revision(
  p_revision_id uuid,
  p_idempotency_key uuid,
  p_actor_name text DEFAULT NULL
)
RETURNS public.project_gantt_revisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  row public.project_gantt_revisions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Необходима авторизация';
  END IF;

  UPDATE public.project_gantt_revisions
  SET status = 'leading_review',
      submitted_by = auth.uid(),
      submitted_by_name = p_actor_name,
      submitted_at = now(),
      updated_at = now()
  WHERE id = p_revision_id
    AND status IN ('draft', 'rework')
  RETURNING * INTO row;

  IF row.id IS NULL THEN
    RAISE EXCEPTION 'Ревизию нельзя отправить в текущем статусе';
  END IF;

  INSERT INTO public.project_gantt_lifecycle_history (
    project_entity_id, project_record_id, revision_id, action,
    old_status, new_status, actor_id, actor_name
  ) VALUES (
    row.project_entity_id, row.project_record_id, row.id, 'revision.submit',
    'draft', 'leading_review', auth.uid(), p_actor_name
  );

  RETURN row;
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_project_gantt_revision(uuid, uuid, text)
  TO authenticated;

CREATE OR REPLACE FUNCTION public.decide_project_gantt_revision(
  p_revision_id uuid,
  p_department_id text,
  p_decision text,
  p_comment text DEFAULT NULL,
  p_idempotency_key uuid DEFAULT NULL,
  p_actor_name text DEFAULT NULL
)
RETURNS public.project_gantt_revisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  row public.project_gantt_revisions%ROWTYPE;
  decision_row public.project_gantt_revision_decisions%ROWTYPE;
  pending_required integer;
  rejected_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Необходима авторизация';
  END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'Некорректное решение';
  END IF;
  IF p_decision = 'reject' AND NULLIF(btrim(COALESCE(p_comment, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Для отказа обязателен комментарий';
  END IF;

  SELECT * INTO row FROM public.project_gantt_revisions WHERE id = p_revision_id;
  IF row.id IS NULL THEN
    RAISE EXCEPTION 'Ревизия не найдена';
  END IF;

  UPDATE public.project_gantt_revision_decisions
  SET decision = CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END,
      comment = p_comment,
      decided_by = auth.uid(),
      decided_by_name = p_actor_name,
      decided_at = now(),
      updated_at = now()
  WHERE revision_id = p_revision_id
    AND department_id = p_department_id
    AND decision = 'pending'
  RETURNING * INTO decision_row;

  IF decision_row.id IS NULL THEN
    RAISE EXCEPTION 'Решение недоступно для этого отдела';
  END IF;

  IF p_decision = 'reject' THEN
    UPDATE public.project_gantt_revisions
    SET status = 'rework',
        returned_at = now(),
        updated_at = now()
    WHERE id = p_revision_id
    RETURNING * INTO row;

    UPDATE public.project_gantt_revision_decisions
    SET decision = 'superseded', updated_at = now()
    WHERE revision_id = p_revision_id AND decision = 'pending';

    INSERT INTO public.project_gantt_lifecycle_history (
      project_entity_id, project_record_id, revision_id, action,
      old_status, new_status, comment, actor_id, actor_name
    ) VALUES (
      row.project_entity_id, row.project_record_id, row.id, 'revision.reject',
      'leading_review', 'rework', p_comment, auth.uid(), p_actor_name
    );
    RETURN row;
  END IF;

  -- Leading approve moves to department_review.
  IF decision_row.role = 'leading' AND row.status = 'leading_review' THEN
    UPDATE public.project_gantt_revisions
    SET status = 'department_review', updated_at = now()
    WHERE id = p_revision_id
    RETURNING * INTO row;
  END IF;

  SELECT COUNT(*) INTO pending_required
  FROM public.project_gantt_revision_decisions
  WHERE revision_id = p_revision_id
    AND required
    AND decision = 'pending';

  SELECT COUNT(*) INTO rejected_count
  FROM public.project_gantt_revision_decisions
  WHERE revision_id = p_revision_id AND decision = 'rejected';

  IF pending_required = 0 AND rejected_count = 0 THEN
    UPDATE public.project_gantt_revisions
    SET status = 'approved', approved_at = now(), updated_at = now()
    WHERE id = p_revision_id
    RETURNING * INTO row;

    -- Auto-publish on full approval.
    UPDATE public.project_gantt_revisions
    SET status = 'published',
        published_at = now(),
        published_by = auth.uid(),
        published_by_name = p_actor_name,
        updated_at = now()
    WHERE id = p_revision_id
    RETURNING * INTO row;

    UPDATE public.project_gantt_revisions
    SET status = 'superseded', updated_at = now()
    WHERE project_entity_id = row.project_entity_id
      AND project_record_id = row.project_record_id
      AND status = 'published'
      AND id <> row.id;

    UPDATE public.project_work_items
    SET is_operationally_published = true,
        published_gantt_revision_id = row.id,
        updated_at = now()
    WHERE project_entity_id = row.project_entity_id
      AND project_record_id = row.project_record_id;

    UPDATE public.project_gantt_project_state
    SET published_gantt_revision_id = row.id,
        operational_plan_state = 'published',
        baseline_gantt_revision_id = COALESCE(baseline_gantt_revision_id, row.id),
        baseline_gantt_fixed_at = COALESCE(baseline_gantt_fixed_at, now()),
        baseline_gantt_fixed_by = COALESCE(baseline_gantt_fixed_by, auth.uid()),
        baseline_gantt_fixed_by_name = COALESCE(
          baseline_gantt_fixed_by_name, p_actor_name
        ),
        updated_at = now()
    WHERE project_entity_id = row.project_entity_id
      AND project_record_id = row.project_record_id;

    INSERT INTO public.project_gantt_lifecycle_history (
      project_entity_id, project_record_id, revision_id, action,
      old_status, new_status, actor_id, actor_name
    ) VALUES (
      row.project_entity_id, row.project_record_id, row.id, 'revision.approve',
      'department_review', 'published', auth.uid(), p_actor_name
    );
  ELSE
    INSERT INTO public.project_gantt_lifecycle_history (
      project_entity_id, project_record_id, revision_id, action,
      comment, actor_id, actor_name
    ) VALUES (
      row.project_entity_id, row.project_record_id, row.id, 'revision.approve',
      p_comment, auth.uid(), p_actor_name
    );
  END IF;

  RETURN row;
END;
$$;

GRANT EXECUTE ON FUNCTION public.decide_project_gantt_revision(
  uuid, text, text, text, uuid, text
) TO authenticated;
-- <<< END 20261101140000_project_gantt_lifecycle.sql

-- >>> BEGIN 20261101150000_automation_complete_skip_supersede.sql
-- Fix: completing beforeEnter must not re-spawn the same prep task.
--
-- complete_automation_task lands the destination stage with inside_complete=1.
-- Rework supersede was cancelling that just-completed beforeEnter (matched by
-- template.trigger_option_id = destination), so the same-stage beforeEnter arm
-- inserted a duplicate pending task after «Готово».
--
-- Skip supersede while inside_complete; keep full supersede for UI rework and
-- automation_ensure_before_enter_prep.

create or replace function public.automation_spawn_on_record_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_values jsonb := '{}'::jsonb;
  new_values jsonb := '{}'::jsonb;
  proc public.automation_processes%rowtype;
  scenario public.automation_scenarios%rowtype;
  tmpl public.automation_task_templates%rowtype;
  old_opt text;
  new_opt text;
  old_opt_id text;
  new_opt_id text;
  entered boolean;
  depth text;
  actor text;
  stored_option_id text;
  v_launch_phase text;
  store_on_prev boolean;
  is_prep_from_prev boolean;
  release_mode text;
  has_earlier boolean;
begin
  depth := coalesce(current_setting('automation.execution_depth', true), '0');
  if depth <> '' and depth::integer > 0 then
    return NEW;
  end if;

  if TG_OP <> 'INSERT' then
    old_values := coalesce(OLD.field_values, '{}'::jsonb);
  end if;
  if TG_OP <> 'DELETE' then
    new_values := coalesce(NEW.field_values, '{}'::jsonb);
  end if;

  actor := coalesce(auth.uid()::text, null);

  for proc in
    select *
    from public.automation_processes p
    where p.entity_id = NEW.entity_id
      and p.enabled = true
      and p.trigger_field_id <> ''
  loop
    old_opt := coalesce(old_values->>proc.trigger_field_id, '');
    new_opt := coalesce(new_values->>proc.trigger_field_id, '');
    old_opt_id := coalesce((public.automation_field_ids(old_opt))[1], '');
    new_opt_id := coalesce((public.automation_field_ids(new_opt))[1], '');

    if TG_OP = 'UPDATE'
       and old_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_assert_no_blocking(
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        old_opt_id
      );
    end if;

    entered := false;
    if proc.trigger_kind = 'recordCreated' and TG_OP = 'INSERT' then
      entered := true;
    elsif proc.trigger_kind = 'recordUpdated' and TG_OP = 'UPDATE' then
      entered := old_values is distinct from new_values;
    elsif proc.trigger_kind in ('fieldEnter', 'fieldTransition') then
      entered := new_opt_id is distinct from old_opt_id and new_opt_id <> '';
    elsif proc.trigger_kind = 'fieldLeave' then
      entered := new_opt_id is distinct from old_opt_id and old_opt_id <> '';
    end if;

    if not entered then
      continue;
    end if;

    select * into scenario
    from public.automation_scenarios s
    where s.process_id = proc.id
      and s.is_default = false
      and jsonb_typeof(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) = 'array'
      and jsonb_array_length(coalesce(s.entry_conditions->'rules', '[]'::jsonb)) > 0
      and public.automation_conditions_match(s.entry_conditions, new_values, old_values)
    order by s.priority desc, s.created_at asc
    limit 1;

    if not found then
      select * into scenario
      from public.automation_scenarios s
      where s.process_id = proc.id
        and s.is_default = true
      order by (
          select count(*)::int
          from public.automation_task_templates t
          where t.scenario_id = s.id
            and coalesce(t.enabled, true) = true
        ) desc,
        s.created_at asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    -- Rework supersede: free prior completed tasks on manual / ensure_before_enter
    -- lands only. During complete_automation_task (inside_complete=1) supersede
    -- would cancel the just-finished beforeEnter prep (template targets
    -- destination) and the same-stage beforeEnter arm would spawn a duplicate.
    if coalesce(current_setting('automation.inside_complete', true), '') <> '1'
       and new_opt_id <> ''
       and old_opt_id is distinct from new_opt_id
    then
      perform public.automation_supersede_stage_tasks(
        NEW.id,
        proc.id,
        new_opt_id
      );
    end if;

    for tmpl in
      select *
      from public.automation_task_templates t
      where t.scenario_id = scenario.id
        and coalesce(t.enabled, true) = true
        and public.automation_conditions_match(t.launch_conditions, new_values, old_values)
        and (
          (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'onEnter'
            and (
              t.trigger_option_id = ''
              or t.trigger_option_id = new_opt
              or t.trigger_option_id = new_opt_id
              or t.trigger_option_id = any(public.automation_field_ids(new_opt))
            )
          )
          or (
            coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
            and (
              exists (
                select 1
                from jsonb_array_elements(
                  coalesce(scenario.stage_transitions, '[]'::jsonb)
                ) st
                where coalesce(st->>'fromOptionId', st->>'from_option_id', '')
                      in (new_opt_id, new_opt)
                  and coalesce(st->>'toOptionId', st->>'to_option_id', '')
                      = t.trigger_option_id
              )
              or (
                (
                  t.trigger_option_id = new_opt
                  or t.trigger_option_id = new_opt_id
                  or t.trigger_option_id = any(public.automation_field_ids(new_opt))
                )
                and not exists (
                  select 1
                  from public.automation_tasks existing
                  where existing.record_id = NEW.id
                    and existing.template_id = t.id
                    and existing.status in ('pending', 'returned', 'completed')
                )
              )
            )
          )
        )
      order by
        case
          when coalesce(nullif(t.launch_phase, ''), 'onEnter') = 'beforeEnter'
            then 0
          else 1
        end,
        t.step_order asc,
        t.created_at asc,
        t.id asc
    loop
      v_launch_phase := coalesce(nullif(tmpl.launch_phase, ''), 'onEnter');

      is_prep_from_prev :=
        v_launch_phase = 'beforeEnter'
        and exists (
          select 1
          from jsonb_array_elements(
            coalesce(scenario.stage_transitions, '[]'::jsonb)
          ) st
          where coalesce(st->>'fromOptionId', st->>'from_option_id', '')
                in (new_opt_id, new_opt)
            and coalesce(st->>'toOptionId', st->>'to_option_id', '')
                = tmpl.trigger_option_id
        );

      store_on_prev := is_prep_from_prev;

      release_mode := coalesce(
        nullif(scenario.stage_task_release->>tmpl.trigger_option_id, ''),
        'parallel'
      );

      if release_mode = 'sequential' then
        select exists (
          select 1
          from public.automation_task_templates earlier
          where earlier.scenario_id = scenario.id
            and coalesce(earlier.enabled, true) = true
            and earlier.trigger_option_id = tmpl.trigger_option_id
            and coalesce(nullif(earlier.launch_phase, ''), 'onEnter') = v_launch_phase
            and (
              earlier.step_order < tmpl.step_order
              or (
                earlier.step_order = tmpl.step_order
                and (
                  earlier.created_at < tmpl.created_at
                  or (
                    earlier.created_at = tmpl.created_at
                    and earlier.id < tmpl.id
                  )
                )
              )
            )
            and public.automation_conditions_match(
              earlier.launch_conditions,
              new_values,
              old_values
            )
        ) into has_earlier;
        if has_earlier then
          continue;
        end if;

        if v_launch_phase = 'onEnter' then
          select exists (
            select 1
            from public.automation_task_templates be
            where be.scenario_id = scenario.id
              and coalesce(be.enabled, true) = true
              and be.trigger_option_id = tmpl.trigger_option_id
              and coalesce(nullif(be.launch_phase, ''), 'onEnter') = 'beforeEnter'
              and public.automation_conditions_match(
                be.launch_conditions,
                new_values,
                old_values
              )
              and (
                (
                  be.kind not in ('autofill', 'actions')
                  and not exists (
                    select 1
                    from public.automation_tasks done
                    where done.record_id = NEW.id
                      and done.template_id = be.id
                      and done.status = 'completed'
                  )
                )
                or (
                  be.kind in ('autofill', 'actions')
                  and not exists (
                    select 1
                    from public.automation_tasks spawned
                    where spawned.record_id = NEW.id
                      and spawned.template_id = be.id
                      and spawned.status in ('pending', 'returned', 'completed')
                  )
                )
              )
          ) into has_earlier;
          if has_earlier then
            continue;
          end if;
        end if;
      end if;

      if store_on_prev then
        stored_option_id := coalesce(nullif(new_opt_id, ''), new_opt);
      else
        stored_option_id := coalesce(
          nullif(tmpl.trigger_option_id, ''),
          nullif(new_opt_id, ''),
          new_opt
        );
      end if;

      perform public.automation_spawn_template_for_record(
        tmpl,
        proc.id,
        NEW.entity_id,
        NEW.id,
        proc.trigger_field_id,
        stored_option_id,
        new_values,
        old_values,
        actor
      );
    end loop;
  end loop;

  return NEW;
end;
$$;
-- <<< END 20261101150000_automation_complete_skip_supersede.sql

